import type { ContractsByEquipment } from "../data/types";
import type { FleetSummary } from "./fleet";

// Costo de mantenimiento: contrato mensual vigente de cada equipo (en USD), lo pagado en los meses
// considerados (importe mensual × cantidad de meses) y ese acumulado dividido por los estudios hechos.
// Un contrato puede tener parte en pesos (p. ej. Siemens): se convierte con la cotización informada.
// Se usa el contrato VIGENTE para todos los meses considerados (la hoja no guarda contratos anteriores).

export interface ContractCost {
  label: string;
  /** El equipo tiene contrato cargado. */
  hasContract: boolean;
  /** Importe mensual en USD (con la parte en pesos convertida), o null sin contrato. */
  monthlyUsd: number | null;
  /** Parte en pesos del contrato (mensual), sin convertir. */
  monthlyArs: number;
  /** La parte en pesos está incluida en `monthlyUsd` (hay cotización) o falta convertirla. */
  complete: boolean;
  /** Meses considerados. */
  months: number;
  /** Lo pagado en los meses considerados (USD). */
  accumulatedUsd: number | null;
  /** Estudios hechos en esos meses. */
  studies: number;
  /** Acumulado / estudios (USD por estudio), o null si no hay contrato o estudios. */
  perStudyUsd: number | null;
  /** Cobertura del contrato (FULL, Top...). */
  coverage: string;
}

export interface ContractSummary {
  rows: ContractCost[];
  /** Total de la flota activa: contratos sumados / estudios de los equipos con contrato. */
  total: ContractCost;
  /** Cotización usada (pesos por USD), o null si no hay. */
  rate: number | null;
  /** Hay contratos con parte en pesos que no se pudieron convertir (falta cotización). */
  missingRate: boolean;
  /** Equipos activos sin contrato cargado. */
  withoutContract: string[];
}

/** Importe mensual en USD de un contrato: parte en USD + parte en pesos / cotización. */
export const contractMonthlyUsd = (c: { ars: number; usd: number }, rate: number | null): { usd: number; complete: boolean } => {
  if (c.ars > 0 && !(rate !== null && rate > 0)) return { usd: c.usd, complete: false };
  return { usd: c.usd + (c.ars > 0 && rate !== null ? c.ars / rate : 0), complete: true };
};

/**
 * Costos de mantenimiento de cada equipo de una tabla de flota (la real o la simulada).
 * `fleet.rows` trae los estudios de cada equipo en los meses considerados (`fleet.months`).
 */
export const contractSummary = (
  contracts: ContractsByEquipment,
  fleet: FleetSummary,
  rate: number | null
): ContractSummary => {
  const months = fleet.months;
  const rows: ContractCost[] = fleet.rows.map((r) => {
    const c = contracts[r.eq];
    if (!c) {
      return { label: r.eq, hasContract: false, monthlyUsd: null, monthlyArs: 0, complete: true, months, accumulatedUsd: null, studies: r.studies, perStudyUsd: null, coverage: "" };
    }
    const m = contractMonthlyUsd(c, rate);
    const accumulated = m.usd * months;
    return {
      label: r.eq, hasContract: true, monthlyUsd: m.usd, monthlyArs: c.ars, complete: m.complete, months,
      accumulatedUsd: accumulated, studies: r.studies, perStudyUsd: r.studies > 0 ? accumulated / r.studies : null, coverage: c.coverage,
    };
  });

  const active = fleet.rows.map((r, i) => ({ row: r, cost: rows[i] })).filter((x) => x.row.isActive);
  const withContract = active.filter((x) => x.cost.hasContract);
  const monthly = withContract.reduce((a, x) => a + (x.cost.monthlyUsd || 0), 0);
  const accumulated = withContract.reduce((a, x) => a + (x.cost.accumulatedUsd || 0), 0);
  const studies = withContract.reduce((a, x) => a + x.cost.studies, 0);
  const total: ContractCost = {
    label: "Total flota activa", hasContract: withContract.length > 0,
    monthlyUsd: withContract.length > 0 ? monthly : null,
    monthlyArs: withContract.reduce((a, x) => a + x.cost.monthlyArs, 0),
    complete: withContract.every((x) => x.cost.complete), months,
    accumulatedUsd: withContract.length > 0 ? accumulated : null, studies,
    perStudyUsd: withContract.length > 0 && studies > 0 ? accumulated / studies : null, coverage: "",
  };
  return {
    rows, total, rate,
    missingRate: rows.some((r) => !r.complete),
    withoutContract: active.filter((x) => !x.cost.hasContract).map((x) => x.row.eq),
  };
};
