import { MONTH_NAMES } from "../config";
import { Dataset, HierarchyEntry } from "../data/types";
import { NO_CATEGORY } from "./grouping";
import { availHours as availHoursOf } from "./hours";
import { ExtraLoad } from "./matrix";
import { CustomTimes, minutesFor } from "./times";

/**
 * Simulador de flota: se "apagan" equipos y sus estudios se reparten entre los
 * que siguen activos según porcentajes cargados por el usuario.
 * Regla (intencional): un porcentaje cargado para un estudio anula el de su
 * categoría secundaria, y éste el de la principal.
 */

/** Claves: `E:estudio`, `S:principal|secundaria`, `P:principal` -> { equipo: % }. */
export type DistributionInputs = Record<string, Record<string, number>>;

export interface SimulationParams {
  year: number;
  disabledEqs: string[];
  distribution: DistributionInputs;
  /** Meses sin datos del AÑO SIMULADO (no del año elegido en el dashboard). */
  excludedMonths: Set<string>;
}

type Source = Pick<Dataset, "equipments" | "times" | "hours" | "hoursByEquipment" | "monthlyQuantities" | "studyTypes" | "studyHierarchy">;

const parentKeys = (h: HierarchyEntry | undefined) => ({
  p: (h && h.principal) || NO_CATEGORY,
  s: (h && h.secundaria) || NO_CATEGORY,
});

export const healthyEquipments = (ds: Pick<Dataset, "equipments">, disabledEqs: string[]): string[] =>
  ds.equipments.filter((eq) => disabledEqs.indexOf(eq) === -1);

/** % del estudio que va al equipo `eq` (0-100) según la regla estudio > secundaria > principal. */
export const resolveDistribution = (
  hierarchy: Record<string, HierarchyEntry>,
  distribution: DistributionInputs,
  estudio: string,
  eq: string
): number => {
  const { p, s } = parentKeys(hierarchy[estudio]);
  const keys = [`E:${estudio}`, `S:${p}|${s}`, `P:${p}`];
  for (let i = 0; i < keys.length; i++) {
    const d = distribution[keys[i]];
    if (d && Object.keys(d).length > 0) return d[eq] || 0;
  }
  return 0;
};

/** Estudios de los equipos apagados (cantidad en los meses con datos del año simulado). */
export const orphanedStudies = (ds: Source, p: SimulationParams): Record<string, number> => {
  const counts: Record<string, number> = {};
  if (!p.year || p.disabledEqs.length === 0) return counts;
  p.disabledEqs.forEach((eq) => {
    MONTH_NAMES.forEach((m) => {
      if (p.excludedMonths.has(m)) return;
      const mq = (ds.monthlyQuantities[eq] && ds.monthlyQuantities[eq][p.year] && ds.monthlyQuantities[eq][p.year][m]) || {};
      Object.keys(mq).forEach((st) => {
        counts[st] = (counts[st] || 0) + mq[st];
      });
    });
  });
  return counts;
};

/** Árbol principal -> secundaria -> estudios, sólo con los estudios a reubicar. */
export const simulationHierarchy = (
  ds: Pick<Dataset, "studyTypes" | "studyHierarchy">,
  orphaned: Record<string, number>
): Record<string, Record<string, string[]>> => {
  const tree: Record<string, Record<string, string[]>> = {};
  ds.studyTypes.forEach((st) => {
    if (!orphaned[st]) return;
    const { p, s } = parentKeys(ds.studyHierarchy[st]);
    if (!tree[p]) tree[p] = {};
    if (!tree[p][s]) tree[p][s] = [];
    tree[p][s].push(st);
  });
  return tree;
};

export const nodeStudies = (
  tree: Record<string, Record<string, string[]>>,
  level: "P" | "S" | "E",
  p: string,
  s?: string,
  e?: string
): string[] => {
  if (level === "P") {
    const out: string[] = [];
    Object.keys(tree[p] || {}).forEach((k) => out.push(...tree[p][k]));
    return out;
  }
  if (level === "S" && s) return (tree[p] && tree[p][s]) || [];
  return e ? [e] : [];
};

/** Estudios a reubicar en un nodo del árbol. */
export const nodeLoad = (
  tree: Record<string, Record<string, string[]>>,
  orphaned: Record<string, number>,
  level: "P" | "S" | "E",
  p: string,
  s?: string,
  e?: string
): number => nodeStudies(tree, level, p, s, e).reduce((acc, st) => acc + (orphaned[st] || 0), 0);

/** % de la carga de un nodo que ya está asignada a equipos activos (0-100). */
export const effectiveAllocation = (
  ds: Pick<Dataset, "equipments" | "studyHierarchy">,
  p: SimulationParams,
  tree: Record<string, Record<string, string[]>>,
  orphaned: Record<string, number>,
  level: "P" | "S" | "E",
  pName: string,
  sName?: string,
  eName?: string
): number => {
  let totalQty = 0;
  let allocatedQty = 0;
  const healthy = healthyEquipments(ds, p.disabledEqs);
  nodeStudies(tree, level, pName, sName, eName).forEach((st) => {
    const qty = orphaned[st] || 0;
    if (qty > 0) {
      totalQty += qty;
      let sumPct = 0;
      healthy.forEach((eq) => {
        sumPct += resolveDistribution(ds.studyHierarchy, p.distribution, st, eq);
      });
      allocatedQty += qty * (sumPct / 100);
    }
  });
  return totalQty > 0 ? (allocatedQty / totalQty) * 100 : 0;
};

export interface SimMonth {
  extraCount: number;
  extraMins: number;
  originalCount: number;
  originalMins: number;
  availHours: number;
  isExcluded: boolean;
}
export type SimMonthly = Record<string, Record<string, SimMonth>>;

/**
 * Carga mensual de cada equipo activo: la propia más la reubicada. Usa los
 * tiempos simulados de cada equipo (y estudio) si los hay.
 * `transferred` guarda qué estudios llegan a cada equipo y mes, para las
 * matrices y los desgloses.
 */
export const simulateMonthly = (
  ds: Source,
  custom: CustomTimes,
  p: SimulationParams
): { monthly: SimMonthly; transferred: ExtraLoad } => {
  const healthy = healthyEquipments(ds, p.disabledEqs);
  const monthly: SimMonthly = {};
  const transferred: ExtraLoad = {};

  healthy.forEach((eq) => {
    monthly[eq] = {};
    transferred[eq] = {};
    MONTH_NAMES.forEach((m) => {
      const cell: SimMonth = {
        extraCount: 0,
        extraMins: 0,
        originalCount: 0,
        originalMins: 0,
        availHours: availHoursOf(ds, eq, p.year, m),
        isExcluded: p.excludedMonths.has(m),
      };
      const own = (ds.monthlyQuantities[eq] && ds.monthlyQuantities[eq][p.year] && ds.monthlyQuantities[eq][p.year][m]) || {};
      Object.keys(own).forEach((st) => {
        cell.originalCount += own[st];
        cell.originalMins += own[st] * minutesFor(ds, custom, eq, st);
      });
      monthly[eq][m] = cell;
    });
  });

  p.disabledEqs.forEach((dEq) => {
    MONTH_NAMES.forEach((m) => {
      if (p.excludedMonths.has(m)) return;
      const studies = (ds.monthlyQuantities[dEq] && ds.monthlyQuantities[dEq][p.year] && ds.monthlyQuantities[dEq][p.year][m]) || {};
      Object.keys(studies).forEach((st) => {
        const qty = studies[st];
        if (qty <= 0) return;
        healthy.forEach((hEq) => {
          const pct = resolveDistribution(ds.studyHierarchy, p.distribution, st, hEq) / 100;
          if (pct > 0) {
            const moved = qty * pct;
            monthly[hEq][m].extraCount += moved;
            monthly[hEq][m].extraMins += moved * minutesFor(ds, custom, hEq, st);
            if (!transferred[hEq][m]) transferred[hEq][m] = {};
            transferred[hEq][m][st] = (transferred[hEq][m][st] || 0) + moved;
          }
        });
      });
    });
  });

  return { monthly, transferred };
};

export interface HealthyStat {
  baseUsedMins: number;
  baseAvailMins: number;
  extraMins: number;
  baseUtil: number;
  simUtil: number;
  /** Estudios que llegan a un equipo que no los hace (tiempo por defecto en el catálogo): estudio -> cantidad. */
  incompatible: Record<string, number>;
}

export const healthyStats = (
  ds: Pick<Dataset, "equipments" | "times" | "studyHierarchy">,
  p: SimulationParams,
  orphaned: Record<string, number>,
  monthly: SimMonthly
): Record<string, HealthyStat> => {
  const stats: Record<string, HealthyStat> = {};
  const healthy = healthyEquipments(ds, p.disabledEqs);

  healthy.forEach((eq) => {
    let availMins = 0;
    let baseMins = 0;
    let extMins = 0;
    MONTH_NAMES.forEach((m) => {
      const s = monthly[eq] ? monthly[eq][m] : undefined;
      if (s && !s.isExcluded) {
        availMins += s.availHours * 60;
        baseMins += s.originalMins;
        extMins += s.extraMins;
      }
    });
    stats[eq] = {
      baseUsedMins: baseMins,
      baseAvailMins: availMins,
      extraMins: extMins,
      baseUtil: availMins > 0 ? (baseMins / availMins) * 100 : 0,
      simUtil: 0,
      incompatible: {},
    };
  });

  Object.keys(orphaned).forEach((st) => {
    const qty = orphaned[st];
    if (qty <= 0) return;
    healthy.forEach((eq) => {
      const pct = resolveDistribution(ds.studyHierarchy, p.distribution, st, eq) / 100;
      if (pct > 0) {
        const rec = ds.times[eq] ? ds.times[eq][st] : undefined;
        const isDefault = rec ? rec.isDefault : true;
        if (isDefault) stats[eq].incompatible[st] = (stats[eq].incompatible[st] || 0) + qty * pct;
      }
    });
  });

  healthy.forEach((eq) => {
    const s = stats[eq];
    s.simUtil = s.baseAvailMins > 0 ? ((s.baseUsedMins + s.extraMins) / s.baseAvailMins) * 100 : 0;
  });
  return stats;
};

export interface SimChartMonth {
  mes: string;
  HorasHabiles: number;
  HorasTrabajadasOriginal: number;
  HorasTrabajadasSimuladas: number;
  UtilizacionHoras: number;
  UtilizacionHorasSimulada: number;
  EstudiosSimulados: number;
  EstudiosOriginales: number;
  isExcluded: boolean;
}

/** Serie mensual de un equipo: situación original vs. simulada. */
export const simulationSeries = (monthly: SimMonthly, eq: string): SimChartMonth[] => {
  if (!eq || !monthly[eq]) return [];
  return MONTH_NAMES.map((m) => {
    const s = monthly[eq][m];
    const originalHours = s.originalMins / 60;
    const simHours = (s.originalMins + s.extraMins) / 60;
    return {
      mes: m,
      HorasHabiles: s.availHours,
      HorasTrabajadasOriginal: originalHours,
      HorasTrabajadasSimuladas: simHours,
      UtilizacionHoras: s.availHours > 0 ? (originalHours / s.availHours) * 100 : 0,
      UtilizacionHorasSimulada: s.availHours > 0 ? (simHours / s.availHours) * 100 : 0,
      EstudiosSimulados: s.originalCount + s.extraCount,
      EstudiosOriginales: s.originalCount,
      isExcluded: s.isExcluded,
    };
  });
};

export interface SimGridCell {
  actual: number;
  util: number;
  usedHours: number;
  availHours: number;
  isExcluded: boolean;
}
export interface SimGrid {
  rows: { equipment: string; monthsData: SimGridCell[]; ytd: number }[];
  maxMonthly: number;
  maxYtd: number;
}

/** Equipos activos x meses con la carga simulada. `metric` decide qué valor define el máximo del mapa. */
export const simulatedGrid = (
  ds: Pick<Dataset, "equipments">,
  p: SimulationParams,
  monthly: SimMonthly,
  metric: "cantidad" | "utilizacion"
): SimGrid => {
  let maxM = 0;
  let maxY = 0;
  const rows = healthyEquipments(ds, p.disabledEqs)
    .map((eq) => {
      let ytd = 0;
      const monthsData = MONTH_NAMES.map((m) => {
        const s = monthly[eq][m];
        const count = s.originalCount + s.extraCount;
        const hours = (s.originalMins + s.extraMins) / 60;
        const util = s.availHours > 0 ? (hours / s.availHours) * 100 : 0;
        if (!s.isExcluded) {
          if (count > maxM && metric === "cantidad") maxM = count;
          if (util > maxM && metric === "utilizacion") maxM = util;
          ytd += count;
        }
        return { actual: count, util, usedHours: hours, availHours: s.availHours, isExcluded: s.isExcluded };
      });
      if (ytd > maxY) maxY = ytd;
      return { equipment: eq, monthsData, ytd };
    })
    .sort((a, b) => b.ytd - a.ytd);
  return { rows, maxMonthly: maxM, maxYtd: maxY };
};
