import React, { createContext, useContext, useMemo, useState } from "react";
import { canHash, hashPassword, sameHex } from "./hash";
import { canSeeView, ROLE_CAPABILITIES, RoleCapabilities } from "./permissions";
import { AuthUser, findUser } from "./users";

const SESSION_KEY = "mri_sesion";
// Sal de relleno: se calcula igual aunque el usuario no exista, para no revelar cuáles existen.
const DUMMY_SALT = "00000000000000000000000000000000";

export interface LoginResult {
  ok: boolean;
  error?: string;
}

interface AuthContextValue {
  user: AuthUser | null;
  login: (username: string, password: string) => Promise<LoginResult>;
  logout: () => void;
  canSeeView: (viewId: string) => boolean;
  capabilities: RoleCapabilities;
}

const AuthContext = createContext<AuthContextValue | null>(null);

// El almacenamiento del navegador puede fallar (ventanas privadas, bloqueos): la app anda igual, sin recordar la sesión.
const readSession = (): AuthUser | null => {
  try {
    const name = window.sessionStorage.getItem(SESSION_KEY);
    return name ? findUser(name) || null : null;
  } catch (e) {
    return null;
  }
};
const writeSession = (name: string | null) => {
  try {
    if (name) window.sessionStorage.setItem(SESSION_KEY, name);
    else window.sessionStorage.removeItem(SESSION_KEY);
  } catch (e) {
    /* sin almacenamiento: no se recuerda la sesión */
  }
};

/**
 * Acceso por usuario y contraseña (versión preliminar, con usuarios fijos en src/auth/users.ts).
 * Es un filtro de acceso, no seguridad real. Para pasar a ingreso con mail institucional se reemplaza `login`
 * por el proveedor elegido y el resto de la app no cambia (usa `user`, `canSeeView` y `capabilities`).
 */
export const AuthProvider: React.FC<React.PropsWithChildren<{}>> = ({ children }) => {
  const [user, setUser] = useState<AuthUser | null>(readSession);

  const value = useMemo<AuthContextValue>(() => ({
    user,
    login: async (username, password) => {
      if (!canHash()) return { ok: false, error: "Este navegador no permite verificar contraseñas en esta conexión (hace falta https)." };
      const found = findUser(username);
      const hash = await hashPassword(password, found ? found.salt : DUMMY_SALT);
      if (found && sameHex(hash, found.hash)) {
        writeSession(found.username);
        setUser(found);
        return { ok: true };
      }
      await new Promise((resolve) => setTimeout(resolve, 600));
      return { ok: false, error: "Usuario o contraseña incorrectos." };
    },
    logout: () => {
      writeSession(null);
      setUser(null);
    },
    canSeeView: (viewId) => (user ? canSeeView(user.role, viewId) : false),
    capabilities: user ? ROLE_CAPABILITIES[user.role] : { cargaManual: false, calidadDeDatos: false },
  }), [user]);

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuth = (): AuthContextValue => {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth debe usarse dentro de AuthProvider");
  return ctx;
};
