    if (isExcluded) return 'bg-gray-200 text-gray-400 opacity-50';
    if (val === 0) return 'bg-gray-50 text-gray-400';
    
    if (type === 'utilizacion' && heatmapColorScheme === 'treemap') {
        if (val >= 90) return 'bg-indigo-600 text-white font-bold shadow-sm';
        if (val >= 75) return 'bg-emerald-500 text-white font-bold shadow-sm';
        if (val >= 60) return 'bg-amber-500 text-white font-bold shadow-sm';
        return 'bg-red-500 text-white font-bold shadow-sm';
    }

    let pct = 0;
    if (type === 'cantidad') pct = max > 0 ? val / max : 0;
    else if (type === 'utilizacion' || type === 'porcentaje') pct = val / 100;

    if (type === 'utilizacion' && pct > 1.0) return 'bg-purple-600 text-white font-bold ring-2 ring-purple-300'; 
    if (pct > 0.8) return 'bg-blue-600 text-white font-bold shadow-sm';
