import { DEFAULT_STUDY_MINUTES } from "../config";
import { cleanText, headersOf, IssueCollector, normKey, parseNumber, resolveColumn } from "./normalize";
import { HierarchyEntry, TimeRecord, TimesResult } from "./types";

type Row = Record<string, unknown>;

const STUDY_ALIASES = ["Nombre_estudio", "Estudio [minutos]", "Tipo_de_Estudio"];
const PRIMARY_ALIASES = ["Categoria_principal"];
const SECONDARY_ALIASES = ["Categoria_secundaria"];
const TOTAL_ALIASES = ["Total_Apariciones"];

const NO_CATEGORY = "Sin Categoría";

/**
 * Hoja TIEMPOS_MRI_POR_EQUIPO: una fila por estudio, una columna por equipo.
 * "X", vacío o no numérico = tiempo por defecto (DEFAULT_STUDY_MINUTES).
 * Todas las columnas que no son metadatos se interpretan como equipos.
 */
export const parseTiempos = (rows: Row[]): TimesResult => {
  const issues = new IssueCollector("TIEMPOS");
  const times: Record<string, Record<string, TimeRecord>> = {};
  const hierarchy: Record<string, HierarchyEntry> = {};
  const studies: Record<string, true> = {};
  const headers = headersOf(rows);

  const studyCol = resolveColumn(headers, STUDY_ALIASES);
  if (!studyCol) {
    issues.add("times-no-study-column", "error", 'No se encontró la columna "Nombre_estudio".');
    return { times, studyTypes: [], hierarchy, equipments: [], issues: issues.toArray() };
  }
  const primaryCol = resolveColumn(headers, PRIMARY_ALIASES);
  const secondaryCol = resolveColumn(headers, SECONDARY_ALIASES);
  const totalCol = resolveColumn(headers, TOTAL_ALIASES);

  const meta: Record<string, true> = {};
  [studyCol, primaryCol, secondaryCol, totalCol].forEach((c) => {
    if (c) meta[c] = true;
  });
  STUDY_ALIASES.forEach((a) => {
    const c = resolveColumn(headers, [a]);
    if (c) meta[c] = true;
  });

  const equipmentCols = headers.filter((h) => {
    if (meta[h]) return false;
    const k = normKey(h);
    return k !== "" && k.indexOf("unnamed") === -1;
  });
  const equipmentNames: Record<string, string> = {}; // columna -> nombre limpio
  equipmentCols.forEach((h) => {
    const name = cleanText(h);
    equipmentNames[h] = name;
    times[name] = {};
  });

  if (equipmentCols.length === 0) {
    issues.add("times-no-equipment-columns", "error", "No hay columnas de equipos en el catálogo de tiempos.");
  }

  rows.forEach((row, i) => {
    const study = cleanText(row[studyCol]);
    if (study === "") return;

    if (studies[study]) {
      issues.add(
        "times-duplicate-study",
        "warning",
        "Estudios repetidos en el catálogo (se usa la última fila).",
        `fila ${i + 2}: ${study}`
      );
    }
    studies[study] = true;

    const principal = primaryCol ? cleanText(row[primaryCol]) : "";
    const secundaria = secondaryCol ? cleanText(row[secondaryCol]) : "";
    if (principal === "") issues.add("times-no-primary", "warning", "Estudios sin categoría principal.", study);
    if (secundaria === "") issues.add("times-no-secondary", "info", "Estudios sin categoría secundaria.", study);
    hierarchy[study] = { principal: principal || NO_CATEGORY, secundaria: secundaria || NO_CATEGORY };

    equipmentCols.forEach((h) => {
      const name = equipmentNames[h];
      const raw = row[h];
      const text = cleanText(raw);
      const n = parseNumber(raw);
      if (n !== null && n > 0) {
        times[name][study] = { value: n, isDefault: false };
        return;
      }
      times[name][study] = { value: DEFAULT_STUDY_MINUTES, isDefault: true };
      // "X" o vacío son el caso esperado; cualquier otra cosa merece aviso.
      if (text !== "" && text.toUpperCase() !== "X") {
        issues.add(
          "times-invalid-value",
          "warning",
          `Tiempos no numéricos o <= 0 (se usa el valor por defecto de ${DEFAULT_STUDY_MINUTES} min).`,
          `${name} / ${study}: "${text}"`
        );
      }
    });
  });

  const studyTypes = Object.keys(studies).sort();
  return {
    times,
    studyTypes,
    hierarchy,
    equipments: equipmentCols.map((h) => equipmentNames[h]),
    issues: issues.toArray(),
  };
};
