// Textos de las tablas según el período elegido: solo con un año completo (los 12 meses) se habla de
// "anual"; en cualquier otro caso es "el período seleccionado".

export interface PeriodWording {
  /** El período son exactamente los 12 meses de un año. */
  fullYear: boolean;
  /** Utilización promedio: "Utilización Promedio Anual (2025)" o "Utilización Promedio en el Período Seleccionado". */
  util: string;
  /** Igual para el escenario simulado. */
  simUtil: string;
  /** Estudios totales: "Estudios Totales en el Año (2025)" o "Estudios Totales en el Período Seleccionado". */
  studies: string;
}

/** `months`: cantidad de meses considerados (con datos y no excluidos) del año `year`. */
export const periodWording = (months: number, year: number): PeriodWording => {
  const fullYear = months === 12;
  return {
    fullYear,
    util: fullYear ? `Utilización Promedio Anual (${year})` : "Utilización Promedio en el Período Seleccionado",
    simUtil: fullYear ? `Utilización Simulada (Promedio Anual ${year})` : "Utilización Simulada en el Período Seleccionado",
    studies: fullYear ? `Estudios Totales en el Año (${year})` : "Estudios Totales en el Período Seleccionado",
  };
};
