export type Role = "admin" | "compartido";

export interface AuthUser {
  username: string;
  /** Nombre que se muestra arriba a la derecha. */
  display: string;
  role: Role;
  salt: string;
  hash: string;
}

export const USERS: AuthUser[] = [
  {
    username: "martin",
    display: "Martín",
    role: "admin",
    salt: "788adc0a4496124257d76935a4268907",
    hash: "6ca6c1a299318677d00a39cbc918f564768a8c1ae0666eab3111e447c38acfc8",
  },
  {
    username: "revision",
    display: "Revisión",
    role: "compartido",
    salt: "b89313312406c58843ad8fe8ffeff300",
    hash: "75aeb809eabcade25dc5a7b471a0ecb204310055e9f79bcf1bfaa40b6a806975",
  },
];

/** Busca un usuario sin distinguir mayúsculas ni espacios de los costados. */
export const findUser = (username: string): AuthUser | undefined => {
  const wanted = username.trim().toLowerCase();
  return USERS.filter((u) => u.username === wanted)[0];
};
