import { MONTH_NAMES, TARGET_UTILIZATION } from "../config";
import { Dataset } from "../data/types";
import { availHours as equipmentAvailHours } from "./hours";
import type { ExtraLoad } from "./matrix";
import { CustomTimes, minutesFor } from "./times";

// Vista "¿Alcanza la flota hoy?": utilización por equipo y composición por
// categoría principal, y el desglose en cascada (categoría -> equipos -> agenda
// -> categoría secundaria). Todo en horas, respetando los tiempos simulados.

export const MAIN_CATEGORIES = ["Neuro", "Cuerpo", "Commodities", "Otros"] as const;
export type MainCategory = (typeof MAIN_CATEGORIES)[number];

/** Categoría principal en las cuatro familias del tablero (lo que no se reconoce va a "Otros"). */
export const mainCategory = (principal: string): MainCategory => {
  const p = (principal || "").toLowerCase();
  if (p.indexOf("neuro") !== -1) return "Neuro";
  if (p.indexOf("cuerpo") !== -1) return "Cuerpo";
  if (p.indexOf("commodit") !== -1) return "Commodities";
  return "Otros";
};

type Source = Pick<Dataset, "times" | "monthlyQuantities" | "studyHierarchy">;
type HoursSource = Pick<Dataset, "hours" | "hoursByEquipment">;

export type CategoryHours = Record<MainCategory, number>;
const zero = (): CategoryHours => ({ Neuro: 0, Cuerpo: 0, Commodities: 0, Otros: 0 });
const sum = (c: CategoryHours): number => c.Neuro + c.Cuerpo + c.Commodities + c.Otros;
const toPct = (c: CategoryHours, avail: number): CategoryHours => ({
  Neuro: avail > 0 ? (c.Neuro / avail) * 100 : 0,
  Cuerpo: avail > 0 ? (c.Cuerpo / avail) * 100 : 0,
  Commodities: avail > 0 ? (c.Commodities / avail) * 100 : 0,
  Otros: avail > 0 ? (c.Otros / avail) * 100 : 0,
});

/** Carga de un equipo en un mes: horas y estudios por categoría principal (con la carga reubicada, si hay). */
export const equipmentMonthLoad = (
  ds: Source,
  custom: CustomTimes,
  eq: string,
  year: number,
  mes: string,
  extra?: ExtraLoad
): { hours: CategoryHours; studies: CategoryHours } => {
  const hours = zero();
  const studies = zero();
  const add = (st: string, qty: number): void => {
    const h = ds.studyHierarchy[st];
    const cat = mainCategory(h ? h.principal : "");
    hours[cat] += (qty * minutesFor(ds, custom, eq, st)) / 60;
    studies[cat] += qty;
  };
  const byStudy = (ds.monthlyQuantities[eq] && ds.monthlyQuantities[eq][year] && ds.monthlyQuantities[eq][year][mes]) || {};
  Object.keys(byStudy).forEach((st) => add(st, byStudy[st]));
  const moved = (extra && extra[eq] && extra[eq][mes]) || {};
  Object.keys(moved).forEach((st) => add(st, moved[st]));
  return { hours, studies };
};

/** Suma dos reparticiones por categoría. */
export const addCategories = (a: CategoryHours, b: CategoryHours): CategoryHours => ({
  Neuro: a.Neuro + b.Neuro, Cuerpo: a.Cuerpo + b.Cuerpo, Commodities: a.Commodities + b.Commodities, Otros: a.Otros + b.Otros,
});
export const emptyCategories = zero;
export const sumCategories = sum;

/** Recorre los estudios de un equipo en los meses no excluidos del año. */
const eachStudy = (
  ds: Pick<Dataset, "monthlyQuantities">,
  eq: string,
  year: number,
  excluded: Set<string>,
  cb: (study: string, qty: number) => void
): void => {
  const byMonth = (ds.monthlyQuantities[eq] && ds.monthlyQuantities[eq][year]) || {};
  Object.keys(byMonth).forEach((mes) => {
    if (excluded.has(mes)) return;
    const studies = byMonth[mes];
    Object.keys(studies).forEach((st) => cb(st, studies[st]));
  });
};

/** Recorre la carga extra (estudios reubicados por el simulador) de un equipo en los meses no excluidos. */
const eachExtra = (
  extra: ExtraLoad | undefined,
  eq: string,
  excluded: Set<string>,
  cb: (study: string, qty: number) => void
): void => {
  const byMonth = (extra && extra[eq]) || {};
  Object.keys(byMonth).forEach((mes) => {
    if (excluded.has(mes)) return;
    Object.keys(byMonth[mes]).forEach((st) => cb(st, byMonth[mes][st]));
  });
};

/** Horas hábiles de un equipo en los meses no excluidos (cada equipo usa su tabla de horas). */
const availHoursOf = (ds: HoursSource, eq: string, year: number, excluded: Set<string>): number => {
  let h = 0;
  MONTH_NAMES.forEach((mes) => {
    if (!excluded.has(mes)) h += equipmentAvailHours(ds, eq, year, mes);
  });
  return h;
};

export interface FleetRow {
  eq: string;
  isActive: boolean;
  availHours: number;
  usedHours: CategoryHours;
  totalUsedHours: number;
  /** % de las horas hábiles usado. */
  util: number;
  /** Puntos porcentuales respecto del objetivo. */
  gap: number;
  /** Composición: % de las horas hábiles por categoría. */
  pct: CategoryHours;
  /** Estudios realizados en los meses considerados. */
  studies: number;
  /** Estudios por mes: estudios / cantidad de meses considerados. */
  avgStudiesPerMonth: number;
  /** Minutos promedio por estudio con la mezcla del período (horas usadas / estudios), o null sin estudios. */
  avgMinutes: number | null;
  /**
   * Estudios que corresponden al objetivo de utilización con la mezcla del período: los que cabrían en
   * el objetivo % de las horas hábiles al tiempo promedio por estudio. En el total es la SUMA de los
   * objetivos de cada equipo activo. null si el equipo no tuvo estudios (no hay mezcla para estimarlo).
   */
  targetStudies: number | null;
  /** Estudios realizados menos estudios objetivo (negativo = faltan estudios), o null si no hay objetivo. */
  studyGap: number | null;
}

/** Estudios objetivo: los realizados escalados del % de utilización actual al objetivo (misma mezcla). */
export const targetStudiesOf = (studies: number, util: number): number | null =>
  studies > 0 && util > 0 ? (studies * TARGET_UTILIZATION) / util : null;

export interface FleetSummary {
  rows: FleetRow[];
  /** Total de la flota activa: suma de horas usadas / suma de horas hábiles de cada equipo. */
  total: FleetRow;
  /** Cantidad de meses considerados (los no excluidos). */
  months: number;
}

export interface FleetParams {
  year: number;
  excluded: Set<string>;
  /** Equipos que cuentan en el total y en los gráficos. */
  activeEqs: Set<string>;
  /** Estudios que se suman a la carga de cada equipo (por equipo y mes): lo reubicado por el simulador. */
  extra?: ExtraLoad;
}

export const fleetSummary = (
  ds: Source & HoursSource & Pick<Dataset, "equipments">,
  custom: CustomTimes,
  p: FleetParams
): FleetSummary => {
  const totalUsed = zero();
  let totalAvail = 0;
  let totalStudies = 0;
  let totalTarget = 0;
  let anyTarget = false;
  const months = MONTH_NAMES.filter((m) => !p.excluded.has(m)).length;
  const perMonth = (n: number): number => (months > 0 ? n / months : 0);

  const rows: FleetRow[] = ds.equipments.map((eq) => {
    const avail = availHoursOf(ds, eq, p.year, p.excluded);
    const used = zero();
    let studies = 0;
    const addLoad = (st: string, qty: number): void => {
      studies += qty;
      const hours = (qty * minutesFor(ds, custom, eq, st)) / 60;
      const h = ds.studyHierarchy[st];
      used[mainCategory(h ? h.principal : "")] += hours;
    };
    eachStudy(ds, eq, p.year, p.excluded, addLoad);
    eachExtra(p.extra, eq, p.excluded, addLoad);
    const total = sum(used);
    const util = avail > 0 ? (total / avail) * 100 : 0;
    const isActive = p.activeEqs.has(eq);
    const target = targetStudiesOf(studies, util);
    if (isActive) {
      totalAvail += avail;
      totalStudies += studies;
      if (target !== null) { totalTarget += target; anyTarget = true; }
      (Object.keys(totalUsed) as MainCategory[]).forEach((c) => { totalUsed[c] += used[c]; });
    }
    return {
      eq, isActive, availHours: avail, usedHours: used, totalUsedHours: total,
      util, gap: util - TARGET_UTILIZATION, pct: toPct(used, avail),
      studies, avgStudiesPerMonth: perMonth(studies),
      avgMinutes: studies > 0 ? (total * 60) / studies : null,
      targetStudies: target, studyGap: target === null ? null : studies - target,
    };
  });

  const grand = sum(totalUsed);
  const totalUtil = totalAvail > 0 ? (grand / totalAvail) * 100 : 0;
  return {
    rows,
    total: {
      eq: "Total flota activa", isActive: true, availHours: totalAvail, usedHours: totalUsed,
      totalUsedHours: grand, util: totalUtil, gap: totalUtil - TARGET_UTILIZATION, pct: toPct(totalUsed, totalAvail),
      studies: totalStudies, avgStudiesPerMonth: perMonth(totalStudies),
      avgMinutes: totalStudies > 0 ? (grand * 60) / totalStudies : null,
      targetStudies: anyTarget ? totalTarget : null, studyGap: anyTarget ? totalStudies - totalTarget : null,
    },
    months,
  };
};

// ---------- Detalle mes a mes (ventanas de la tabla) ----------

export interface FleetMonthDetail {
  mes: string;
  /** El mes tiene datos cargados (no es un mes futuro del año). */
  hasData: boolean;
  /** El mes está dentro de la selección de meses (cuenta en el promedio anual). */
  included: boolean;
  availHours: number;
  usedHours: number;
  /** Utilización del mes: horas usadas / horas hábiles. */
  util: number;
  studies: number;
  /**
   * Estudios objetivo del mes: las horas hábiles del mes al objetivo %, con el tiempo promedio por estudio
   * de cada equipo en los meses seleccionados. null en meses fuera de la selección o sin datos.
   * Con base "agenda", las horas son las de agenda abierta (con tope a las horas hábiles) y sólo
   * cuentan los equipos con agenda cargada ese mes.
   */
  targetStudies: number | null;
  /** Estudios del mes que se comparan con el objetivo (los de los equipos que tienen objetivo ese mes). */
  comparedStudies: number | null;
}

/** Sobre qué horas se plantea el objetivo: las de clínica abierta (hábiles) o las de agenda abierta. */
export type TargetBasis = "potential" | "agenda";

/**
 * Mes a mes de un equipo (equipments = [eq]) o de varios sumados (el total de la flota activa).
 * La utilización de varios equipos se pondera por horas, igual que el total de la tabla.
 */
export const fleetMonthlyDetail = (
  ds: Source & HoursSource & Pick<Dataset, "maxMonthPerYear"> & Partial<Pick<Dataset, "agenda">>,
  custom: CustomTimes,
  p: { year: number; excluded: Set<string>; equipments: string[]; extra?: ExtraLoad; targetBasis?: TargetBasis }
): FleetMonthDetail[] => {
  const basis: TargetBasis = p.targetBasis || "potential";
  // Horas sobre las que se plantea el objetivo de un equipo en un mes (null = ese mes no cuenta para el equipo)
  const baseHours = (eq: string, mes: string, avail: number): number | null => {
    if (basis === "potential") return avail;
    const raw = ds.agenda && ds.agenda[eq] && ds.agenda[eq][p.year] ? ds.agenda[eq][p.year][mes] : undefined;
    return raw === undefined ? null : Math.min(raw, avail);
  };
  const maxMonth = ds.maxMonthPerYear ? ds.maxMonthPerYear[p.year] : undefined;
  // Por equipo y mes: horas hábiles, horas usadas y estudios
  const perEq = p.equipments.map((eq) =>
    MONTH_NAMES.map((mes) => {
      let used = 0;
      let studies = 0;
      const byStudy = (ds.monthlyQuantities[eq] && ds.monthlyQuantities[eq][p.year] && ds.monthlyQuantities[eq][p.year][mes]) || {};
      Object.keys(byStudy).forEach((st) => {
        studies += byStudy[st];
        used += (byStudy[st] * minutesFor(ds, custom, eq, st)) / 60;
      });
      const moved = (p.extra && p.extra[eq] && p.extra[eq][mes]) || {};
      Object.keys(moved).forEach((st) => {
        studies += moved[st];
        used += (moved[st] * minutesFor(ds, custom, eq, st)) / 60;
      });
      return { avail: equipmentAvailHours(ds, eq, p.year, mes), used, studies };
    })
  );
  const hasData = MONTH_NAMES.map((_, idx) =>
    maxMonth !== undefined ? idx + 1 <= maxMonth : perEq.reduce((a, e) => a + e[idx].studies, 0) > 0
  );
  // Tiempo promedio por estudio de cada equipo en los meses seleccionados con datos (su mezcla del período)
  const avgMinutes = perEq.map((months, i) => {
    let used = 0;
    let studies = 0;
    months.forEach((m, idx) => {
      if (p.excluded.has(MONTH_NAMES[idx]) || !hasData[idx]) return;
      if (baseHours(p.equipments[i], MONTH_NAMES[idx], m.avail) === null) return;
      used += m.used;
      studies += m.studies;
    });
    return studies > 0 ? (used * 60) / studies : null;
  });
  return MONTH_NAMES.map((mes, idx) => {
    const avail = perEq.reduce((a, e) => a + e[idx].avail, 0);
    const used = perEq.reduce((a, e) => a + e[idx].used, 0);
    const studies = perEq.reduce((a, e) => a + e[idx].studies, 0);
    const included = !p.excluded.has(mes);
    let target: number | null = null;
    let compared: number | null = null;
    if (included && hasData[idx]) {
      perEq.forEach((months, i) => {
        const mins = avgMinutes[i];
        const base = baseHours(p.equipments[i], mes, months[idx].avail);
        if (mins === null || base === null) return;
        target = (target === null ? 0 : target) + (TARGET_UTILIZATION / 100) * base * 60 / mins;
        compared = (compared === null ? 0 : compared) + months[idx].studies;
      });
    }
    return {
      mes,
      hasData: hasData[idx],
      included,
      availHours: avail,
      usedHours: used,
      util: avail > 0 ? (used / avail) * 100 : 0,
      studies,
      targetStudies: target,
      comparedStudies: compared,
    };
  });
};

// ---------- Torta global ----------

export interface PieSlice {
  name: MainCategory | "Tiempo Inutilizado";
  value: number;
}

/** Horas consumidas por categoría de la flota activa (y, opcionalmente, el tiempo no usado). */
export const categoryPie = (total: FleetRow, showUnused: boolean): PieSlice[] => {
  const out: PieSlice[] = [
    { name: "Neuro", value: total.usedHours.Neuro },
    { name: "Cuerpo", value: total.usedHours.Cuerpo },
    { name: "Commodities", value: total.usedHours.Commodities },
  ];
  if (total.usedHours.Otros > 0) out.push({ name: "Otros", value: total.usedHours.Otros });
  if (showUnused) {
    const unused = total.availHours - total.totalUsedHours;
    if (unused > 0) out.push({ name: "Tiempo Inutilizado", value: unused });
  }
  return out;
};

// ---------- Cascada ----------

export interface CategoryEquipmentShare {
  eq: string;
  hours: number;
  qty: number;
  /** % de las horas de la categoría que ejecuta este equipo (entre los equipos activos). */
  pct: number;
}

/** Qué equipos ejecutan una categoría y cuánto de ella (en horas). */
export const categoryEquipmentShare = (
  ds: Source,
  custom: CustomTimes,
  p: { year: number; excluded: Set<string>; equipments: string[]; category: MainCategory }
): CategoryEquipmentShare[] => {
  const raw = p.equipments.map((eq) => {
    let hours = 0;
    let qty = 0;
    eachStudy(ds, eq, p.year, p.excluded, (st, q) => {
      const h = ds.studyHierarchy[st];
      if (mainCategory(h ? h.principal : "") !== p.category) return;
      hours += (q * minutesFor(ds, custom, eq, st)) / 60;
      qty += q;
    });
    return { eq, hours, qty };
  });
  const total = raw.reduce((a, r) => a + r.hours, 0);
  return raw
    .map((r) => ({ ...r, pct: total > 0 ? (r.hours / total) * 100 : 0 }))
    .sort((a, b) => b.hours - a.hours);
};

export interface AgendaSlice {
  name: MainCategory | "Tiempo Inutilizado";
  /** % de las horas hábiles del equipo. */
  pct: number;
}

/** Composición de la agenda de un equipo (categorías + tiempo inutilizado), de mayor a menor. */
export const equipmentAgenda = (row: FleetRow): AgendaSlice[] => {
  const slices: AgendaSlice[] = [
    { name: "Neuro", pct: row.pct.Neuro },
    { name: "Cuerpo", pct: row.pct.Cuerpo },
    { name: "Commodities", pct: row.pct.Commodities },
    { name: "Otros", pct: row.pct.Otros },
    { name: "Tiempo Inutilizado", pct: Math.max(0, 100 - row.util) },
  ];
  return slices.filter((s) => s.pct > 0).sort((a, b) => b.pct - a.pct);
};

export interface SecondaryShare {
  name: string;
  hours: number;
  qty: number;
  /** % de las horas de la categoría en ese equipo. */
  pct: number;
}

/** Desglose por categoría secundaria de una categoría principal en un equipo. */
export const secondaryBreakdown = (
  ds: Source,
  custom: CustomTimes,
  p: { year: number; excluded: Set<string>; eq: string; category: MainCategory }
): SecondaryShare[] => {
  const acc: Record<string, { hours: number; qty: number }> = {};
  let total = 0;
  eachStudy(ds, p.eq, p.year, p.excluded, (st, q) => {
    const h = ds.studyHierarchy[st];
    if (mainCategory(h ? h.principal : "") !== p.category) return;
    const name = (h && h.secundaria) || "Sin Categoría";
    const hours = (q * minutesFor(ds, custom, p.eq, st)) / 60;
    if (!acc[name]) acc[name] = { hours: 0, qty: 0 };
    acc[name].hours += hours;
    acc[name].qty += q;
    total += hours;
  });
  return Object.keys(acc)
    .map((name) => ({ name, hours: acc[name].hours, qty: acc[name].qty, pct: total > 0 ? (acc[name].hours / total) * 100 : 0 }))
    .sort((a, b) => b.hours - a.hours);
};
