import React from "react";
import { ChevronDown, ChevronUp } from "lucide-react";

export interface KpiMetric {
  label: string;
  value: React.ReactNode;
  /** Diferencia destacada junto al valor (p. ej. contra la flota actual en el escenario simulado). */
  delta?: React.ReactNode;
  /** Línea chica debajo del valor (diferencia, contexto). */
  sub?: React.ReactNode;
  /** Explicación al pasar el mouse. */
  title?: string;
}

interface KpiBannerProps {
  title: string;
  icon: React.ReactNode;
  metrics: KpiMetric[];
  open: boolean;
  onToggle: () => void;
  /** Aviso cuando falta una hoja y no hay cifras. */
  emptyMessage?: string;
}

/**
 * Banner con las cifras principales de un grupo de indicadores (los valores del total de la flota activa,
 * como en el pie de la tabla de utilización). Al hacer clic se despliega el detalle por equipo.
 */
export const KpiBanner: React.FC<KpiBannerProps> = ({ title, icon, metrics, open, onToggle, emptyMessage }) => (
  <div
    role="button"
    tabIndex={0}
    onClick={onToggle}
    onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onToggle(); } }}
    aria-expanded={open}
    className={`cursor-pointer text-left bg-white rounded-2xl shadow-sm border overflow-hidden transition-shadow hover:shadow-md focus:outline-none ${open ? 'border-blue-400 ring-2 ring-blue-200' : 'border-gray-200'}`}
  >
    <div className="bg-gray-800 p-4 px-5 flex items-center justify-between gap-3">
      <h3 className="text-base font-bold text-white flex items-center gap-2">{icon} {title}</h3>
      <span className="flex items-center gap-1 text-[10px] font-bold uppercase tracking-wider text-gray-400">
        {open ? 'Ocultar detalle' : 'Ver detalle por equipo'} {open ? <ChevronUp size={14}/> : <ChevronDown size={14}/>}
      </span>
    </div>
    {metrics.length === 0 ? (
      <div className="bg-gray-100 p-6 text-sm text-gray-500">{emptyMessage}</div>
    ) : (
      <div className={`bg-gray-100 p-5 grid grid-cols-2 ${metrics.length >= 5 ? 'sm:grid-cols-5' : 'sm:grid-cols-4'} gap-x-4 gap-y-5`}>
        {metrics.map(m => (
          <div key={m.label} title={m.title}>
            <p className="text-[10px] font-bold text-gray-500 uppercase tracking-wider leading-tight">{m.label}</p>
            <p className="mt-1 text-xl font-black text-gray-800">{m.value}</p>
            {m.delta && <div className="mt-1">{m.delta}</div>}
            {m.sub && <div className="text-[10px] font-bold text-gray-400 mt-0.5">{m.sub}</div>}
          </div>
        ))}
      </div>
    )}
  </div>
);
