import type { Role } from "./users";

// Qué puede ver cada rol. Las pestañas que un rol no tiene NO se muestran ni se abren (el código sigue en la app).
// Los identificadores son los de las pestañas de App.tsx (ViewId).
export const ROLE_VIEWS: Record<Role, string[] | "all"> = {
  admin: "all",
  compartido: ["resumen", "flota", "simulacion", "simresumen"],
};

export interface RoleCapabilities {
  /** Botón de Carga Rápida y carga manual de archivos. */
  cargaManual: boolean;
  /** Panel de calidad de datos. */
  calidadDeDatos: boolean;
}

export const ROLE_CAPABILITIES: Record<Role, RoleCapabilities> = {
  admin: { cargaManual: true, calidadDeDatos: true },
  compartido: { cargaManual: false, calidadDeDatos: false },
};

export const canSeeView = (role: Role, viewId: string): boolean => {
  const views = ROLE_VIEWS[role];
  return views === "all" || views.indexOf(viewId) >= 0;
};
