import { MONTH_NAMES } from "../config";
import { cleanText, headersOf, IssueCollector, normKey, parseMonthIndex, parseNumber } from "./normalize";
import { DataSource, HoursByYearMonth, HoursResult } from "./types";

type Row = Record<string, unknown>;

/**
 * Hoja HORAS_HABILES: una fila por mes, una columna "Horas Hábiles AAAA" por año.
 * Devuelve { año: { "Enero": horas, ... } } con los nombres de mes canónicos.
 * `source` identifica la hoja en el reporte de calidad (hay una por grupo de equipos).
 */
export const parseHoras = (rows: Row[], source: DataSource = "HORAS"): HoursResult => {
  const issues = new IssueCollector(source);
  const hours: HoursByYearMonth = {};
  const headers = headersOf(rows);

  const monthCol = headers.filter((h) => normKey(h) === "mes")[0];
  if (!monthCol) {
    issues.add("hours-no-month-column", "error", 'No se encontró la columna "Mes".');
    return { hours, issues: issues.toArray() };
  }

  const yearCols: Array<{ header: string; year: number }> = [];
  headers.forEach((h) => {
    const m = /^horas habiles\s+(\d{4})$/.exec(normKey(h));
    if (m) yearCols.push({ header: h, year: parseInt(m[1], 10) });
  });
  if (yearCols.length === 0) {
    issues.add("hours-no-year-columns", "error", 'No se encontraron columnas "Horas Hábiles AAAA".');
    return { hours, issues: issues.toArray() };
  }
  yearCols.forEach((c) => {
    hours[c.year] = {};
  });

  rows.forEach((row, i) => {
    const rawMonth = cleanText(row[monthCol]);
    if (rawMonth === "") return; // fila vacía
    const mi = parseMonthIndex(rawMonth);
    if (mi === null) {
      issues.add("hours-unknown-month", "warning", "Meses con nombre no reconocido en HORAS_HABILES.", `fila ${i + 2}: "${rawMonth}"`);
      return;
    }
    const month = MONTH_NAMES[mi];
    yearCols.forEach((c) => {
      const raw = row[c.header];
      const n = parseNumber(raw);
      if (n === null) {
        // Compatibilidad con la versión anterior: celda vacía o inválida = 0 horas.
        issues.add(
          "hours-missing-value",
          "warning",
          "Meses sin horas hábiles cargadas (se toman como 0 y no se calcula utilización).",
          `${month} ${c.year}`
        );
        hours[c.year][month] = 0;
      } else if (n < 0) {
        issues.add("hours-negative", "warning", "Horas hábiles negativas (se toman como 0).", `${month} ${c.year}: ${n}`);
        hours[c.year][month] = 0;
      } else {
        hours[c.year][month] = n;
      }
    });
  });

  return { hours, issues: issues.toArray() };
};
