import React, { useState } from "react";
import { Calendar } from "lucide-react";
import { Bar, BarChart, CartesianGrid, LabelList, Legend, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import * as calc from "../calc";
import { CollapsibleSection } from "../components/CollapsibleSection";
import { useModel } from "../model/ModelContext";

const POTENTIAL_COLOR = "#CBD5E1";
const AGENDA_COLOR = "#3B82F6";
const USED_COLOR = "#10B981";
const formatCount = (n: number) => n.toLocaleString('es-AR', { maximumFractionDigits: 0 });
const formatPct = (v: number | null) => (v === null ? '—' : `${v.toFixed(1)}%`);

/** Cuadro que aparece al pasar el mouse por un grupo de barras. */
const AgendaTooltip = (props: any) => {
  const row = props && props.payload && props.payload[0] ? props.payload[0].payload : null;
  if (!props || !props.active || !row) return null;
  return (
    <div className="bg-white border border-gray-200 rounded-xl shadow-lg p-3 text-xs">
      <p className="font-black text-gray-800 mb-2">{row.name}</p>
      <p className="text-gray-600"><span className="inline-block w-2.5 h-2.5 rounded mr-2" style={{ background: POTENTIAL_COLOR }}></span>Clínica abierta: <b>{formatCount(row.potential)} h</b></p>
      <p className="text-gray-600"><span className="inline-block w-2.5 h-2.5 rounded mr-2" style={{ background: AGENDA_COLOR }}></span>Agenda abierta: <b>{formatCount(row.agenda)} h</b></p>
      <p className="text-gray-600"><span className="inline-block w-2.5 h-2.5 rounded mr-2" style={{ background: USED_COLOR }}></span>Adquisición: <b>{formatCount(row.used)} h</b></p>
      <div className="border-t border-gray-100 mt-2 pt-2 space-y-0.5 text-gray-600">
        <p>Cobertura de agenda: <b>{formatPct(row.coverage)}</b></p>
        <p>Utilización efectiva de agenda: <b>{formatPct(row.effective)}</b></p>
        <p>Adquisición / clínica abierta: <b>{formatPct(row.util)}</b></p>
        <p className="text-gray-400">{row.months} {row.months === 1 ? 'mes' : 'meses'} con agenda{row.capped > 0 ? ` · ${row.capped} con agenda limitada a las horas hábiles` : ''}</p>
      </div>
    </div>
  );
};

/**
 * Vista 1: por equipo (uno, varios o todos, con un consolidado) las horas de clínica abierta,
 * las horas de agenda abierta y las horas efectivas de adquisición de estudios.
 */
export const AgendaCapacitySection: React.FC = () => {
  // Mientras el mouse está sobre el gráfico se ocultan las etiquetas de valor: si no, quedan encima del cuadro
  // de detalle (que ya muestra los mismos valores) y lo tapan.
  const [hovering, setHovering] = useState(false);
  const { data, agendaLoaded, agendaSummary, agendaSelected, toggleAgendaEq, selectAllAgendaEqs, selectNoAgendaEqs, agendaShowDetail, setAgendaShowDetail, agendaChart, selectedYear } = useModel();

  const groups = agendaChart.groups;
  const rows = groups.map(g => ({
    name: g.label,
    potential: g.potentialHours,
    agenda: g.agendaHours,
    used: g.usedHours,
    coverage: g.coverage,
    effective: g.effective,
    util: g.potentialHours > 0 ? (g.usedHours / g.potentialHours) * 100 : null,
    months: g.months,
    capped: g.cappedMonths,
  }));
  const head = groups[0];
  const headUtil = head && head.potentialHours > 0 ? (head.usedHours / head.potentialHours) * 100 : null;
  const capped = agendaSummary ? agendaSummary.rows.filter(r => agendaSelected.indexOf(r.label) !== -1).reduce((a, r) => a + r.cappedMonths, 0) : 0;

  return (
    <CollapsibleSection
      title="Capacidad de Agenda: Clínica Abierta, Agenda y Adquisición"
      subtitle="Cuántas de las horas en que la clínica estuvo abierta tuvo la agenda abierta el equipo, y cuántas se usaron en adquirir estudios."
      icon={<Calendar className="text-blue-600" size={24}/>}
      defaultOpen={true}
    >
      {!agendaLoaded || !agendaSummary ? (
        <div className="text-center p-10 text-gray-500 text-sm">
          Cargá la hoja <b>CAPACIDAD DE AGENDA</b> (o usá Carga Rápida) para ver este gráfico.
        </div>
      ) : (
        <div className="bg-white border border-gray-100 rounded-xl p-6 shadow-sm">
          <div className="flex flex-wrap items-center justify-between gap-3 mb-3">
            <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider">Equipos del gráfico</label>
            <div className="flex items-center gap-4">
              <button onClick={selectAllAgendaEqs} className="text-[10px] font-bold text-blue-600 hover:underline">Todos</button>
              <button onClick={selectNoAgendaEqs} className="text-[10px] font-bold text-blue-600 hover:underline">Ninguno</button>
              <label className="flex items-center gap-2 text-[10px] font-bold text-gray-500 uppercase cursor-pointer select-none">
                <input type="checkbox" checked={agendaShowDetail} onChange={() => setAgendaShowDetail(!agendaShowDetail)} className="w-3.5 h-3.5 text-blue-600 rounded cursor-pointer"/>
                Detalle por equipo
              </label>
            </div>
          </div>
          <div className="flex gap-1.5 flex-wrap mb-6">
            {data.equipments.map(eq => {
              const on = agendaSelected.indexOf(eq) !== -1;
              return (
                <button
                  key={eq}
                  onClick={() => toggleAgendaEq(eq)}
                  className={`px-2.5 py-1.5 text-[10px] font-bold rounded border transition-colors ${on ? 'bg-blue-100 text-blue-800 border-blue-300 shadow-sm' : 'bg-white text-gray-400 border-gray-200 hover:bg-gray-100'}`}
                >{eq}</button>
              );
            })}
          </div>

          {rows.length === 0 ? (
            <div className="text-center p-10 text-gray-500 text-sm">
              {agendaSelected.length === 0
                ? 'Elegí al menos un equipo.'
                : `Los equipos elegidos no tienen datos de agenda en los meses considerados de ${selectedYear}.`}
            </div>
          ) : (
            <>
              <div className="flex flex-wrap gap-3 mb-4">
                <div className="bg-gray-50 border border-gray-200 rounded-lg px-4 py-2">
                  <p className="text-[10px] font-bold text-gray-500 uppercase">{head.label}</p>
                  <p className="text-xs text-gray-500">{head.months} {head.months === 1 ? 'mes' : 'meses'} con agenda</p>
                </div>
                <div className="bg-gray-50 border border-gray-200 rounded-lg px-4 py-2">
                  <p className="text-[10px] font-bold text-gray-500 uppercase">Cobertura de agenda</p>
                  <p className="text-lg font-black text-gray-700">{formatPct(head.coverage)}</p>
                </div>
                <div className="bg-gray-50 border border-gray-200 rounded-lg px-4 py-2">
                  <p className="text-[10px] font-bold text-gray-500 uppercase">Utilización efectiva de agenda</p>
                  <p className="text-lg font-black" style={{ color: head.effective === null ? undefined : calc.utilizationColor(head.effective) }}>{formatPct(head.effective)}</p>
                </div>
                <div className="bg-gray-50 border border-gray-200 rounded-lg px-4 py-2">
                  <p className="text-[10px] font-bold text-gray-500 uppercase">Adquisición / clínica abierta</p>
                  <p className="text-lg font-black" style={{ color: headUtil === null ? undefined : calc.utilizationColor(headUtil) }}>{formatPct(headUtil)}</p>
                </div>
              </div>

              <div className="w-full" style={{ height: rows.length * 96 + 70 }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={rows} layout="vertical" margin={{ top: 5, right: 70, left: 10, bottom: 5 }} barCategoryGap="18%" onMouseEnter={() => setHovering(true)} onMouseLeave={() => setHovering(false)}>
                    <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                    <XAxis type="number" tick={{ fontSize: 12 }} tickFormatter={(v: any) => formatCount(Number(v))} />
                    <YAxis type="category" dataKey="name" width={190} tick={{ fontSize: 11, fontWeight: 700 }} />
                    <Tooltip content={<AgendaTooltip />} cursor={{ fill: '#F3F4F6' }} wrapperStyle={{ zIndex: 1000, outline: 'none' }} />
                    <Legend />
                    <Bar dataKey="potential" name="Horas de clínica abierta (capacidad potencial)" fill={POTENTIAL_COLOR} barSize={18}>
                      {!hovering && <LabelList dataKey="potential" position="right" formatter={(v: any) => `${formatCount(Number(v))} h`} style={{ fontSize: 11, fill: '#6B7280' }} />}
                    </Bar>
                    <Bar dataKey="agenda" name="Horas de agenda disponible (capacidad de agenda abierta)" fill={AGENDA_COLOR} barSize={18}>
                      {!hovering && <LabelList dataKey="agenda" position="right" formatter={(v: any) => `${formatCount(Number(v))} h`} style={{ fontSize: 11, fill: '#6B7280' }} />}
                    </Bar>
                    <Bar dataKey="used" name="Horas efectivas de adquisición (capacidad utilizada)" fill={USED_COLOR} barSize={18}>
                      {!hovering && <LabelList dataKey="used" position="right" formatter={(v: any) => `${formatCount(Number(v))} h`} style={{ fontSize: 11, fill: '#6B7280' }} />}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </>
          )}

          <p className="mt-4 text-[11px] text-gray-400">
            Usa los meses elegidos arriba. La agenda de cada mes se limita a las horas hábiles de la clínica{capped > 0 ? ` (${capped} ${capped === 1 ? 'caso' : 'casos'} en los equipos elegidos)` : ''}.
            Un mes sin dato de agenda de un equipo queda fuera de sus tres barras, para que se puedan comparar.
            {agendaChart.withoutData.length > 0 && ` Sin datos de agenda: ${agendaChart.withoutData.join(', ')}.`}
          </p>
        </div>
      )}
    </CollapsibleSection>
  );
};
