import React from "react";
import { PieChart as PieChartIcon, Eye, EyeOff } from "lucide-react";
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer, Legend } from "recharts";
import * as calc from "../calc";
import { CATEGORY_COLORS } from "../constants";
import { useModel } from "../model/ModelContext";

/** Torta global: horas consumidas por la flota activa según categoría. Un clic abre la cascada. */
export const CategoryDistribution: React.FC = () => {
  const { fleetPie, showUnusedTime, setShowUnusedTime, g1SelectedCategory, setG1SelectedCategory } = useModel();

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-6 flex flex-col md:flex-row items-center gap-8">
      <div className="w-full md:w-1/3 flex flex-col justify-center gap-4">
        <div>
          <h3 className="text-xl font-bold text-gray-800 flex items-center gap-2">
            <PieChartIcon className="text-blue-600"/> Distribución Global
          </h3>
          <p className="text-xs text-gray-500 mt-1">Horas consumidas por la flota activa. Haz clic en una categoría para analizarla.</p>
        </div>
        <button
          onClick={() => setShowUnusedTime(!showUnusedTime)}
          className={`self-start mt-4 px-4 py-2 rounded-xl text-xs font-bold border transition-colors flex items-center gap-2 ${showUnusedTime ? 'bg-slate-700 text-white border-slate-800' : 'bg-white text-gray-500 border-gray-300 hover:bg-gray-50'}`}
        >
          {showUnusedTime ? <EyeOff size={16}/> : <Eye size={16}/>}
          {showUnusedTime ? "Ocultar" : "Mostrar"} Tiempo Inutilizado
        </button>
      </div>
      <div className="w-full md:w-2/3 h-[300px]">
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={fleetPie}
              cx="50%" cy="50%"
              innerRadius={70} outerRadius={120}
              paddingAngle={3}
              dataKey="value"
              onClick={(d: any) => {
                const name = d && d.name;
                if (name && name !== "Tiempo Inutilizado") setG1SelectedCategory(name as calc.MainCategory);
              }}
              className="cursor-pointer outline-none"
            >
              {fleetPie.map(slice => (
                <Cell
                  key={slice.name}
                  fill={CATEGORY_COLORS[slice.name]}
                  stroke={g1SelectedCategory === slice.name ? '#000' : 'none'}
                  strokeWidth={g1SelectedCategory === slice.name ? 3 : 0}
                  className="hover:opacity-80 transition-opacity outline-none"
                />
              ))}
            </Pie>
            <Tooltip
              formatter={(val: any) => [`${Number(val).toFixed(1)} hs`, 'Consumo']}
              contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}
            />
            <Legend layout="vertical" verticalAlign="middle" align="right" />
          </PieChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};
