import { HierarchyEntry } from "../data/types";

export type GroupingLevel = "principal" | "secundaria" | "estudio" | "todo";

export const NO_CATEGORY = "Sin Categoría";
export const TOTAL_LABEL = "Total General";

/**
 * Nombre del grupo de un estudio según el nivel de agrupación.
 * Un estudio que no está en el catálogo cae en "Sin Categoría" (antes, en
 * algunas pantallas quedaba como su propio grupo y en otras como "Sin Categoría").
 */
export const groupKey = (
  hierarchy: Record<string, HierarchyEntry>,
  estudio: string,
  level: GroupingLevel | string
): string => {
  if (level === "todo") return TOTAL_LABEL;
  if (level === "estudio") return estudio;
  const h = hierarchy[estudio];
  if (!h) return NO_CATEGORY;
  return level === "principal" ? h.principal : h.secundaria;
};

/** Categoría de un estudio para filas de matriz (sin nivel "todo"). */
export const rowKey = (
  hierarchy: Record<string, HierarchyEntry>,
  estudio: string,
  level: "principal" | "secundaria" | "estudio"
): string => {
  if (level === "estudio") return estudio;
  const h = hierarchy[estudio];
  const v = level === "principal" ? h?.principal : h?.secundaria;
  return v || NO_CATEGORY;
};
