import React, { createContext, useContext } from "react";
import { useDashboardModel, DashboardModel, ViewId } from "./useDashboardModel";

export type { ViewId };

const ModelContext = createContext<DashboardModel | null>(null);

export const ModelProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const model = useDashboardModel();
  return <ModelContext.Provider value={model}>{children}</ModelContext.Provider>;
};

export const useModel = (): DashboardModel => {
  const model = useContext(ModelContext);
  if (!model) throw new Error("useModel debe usarse dentro de ModelProvider");
  return model;
};
