// Verificación de contraseñas sin guardarlas en claro: PBKDF2-SHA256 con sal propia de cada usuario.
// Usa la API Web Crypto del navegador (https o localhost) y la de Node en las pruebas.
// OJO: esto es un filtro de acceso para una app sin servidor, NO seguridad real (ver README, sección "Acceso").

export const AUTH_ITERATIONS = 150000;
export const AUTH_HASH_BYTES = 32;

export const bytesToHex = (bytes: Uint8Array): string => {
  let out = "";
  for (let i = 0; i < bytes.length; i++) out += (bytes[i] < 16 ? "0" : "") + bytes[i].toString(16);
  return out;
};

export const hexToBytes = (hex: string): Uint8Array => {
  const out = new Uint8Array(Math.floor(hex.length / 2));
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.substr(i * 2, 2), 16);
  return out;
};

const getSubtle = (): any => {
  const c = (globalThis as any).crypto;
  return c && c.subtle ? c.subtle : null;
};

/** true si el navegador permite calcular el hash (hace falta una conexión segura: https o localhost). */
export const canHash = (): boolean => getSubtle() !== null;

/** Hash PBKDF2-SHA256 (hex) de la contraseña con la sal indicada (hex). */
export const hashPassword = async (password: string, saltHex: string): Promise<string> => {
  const subtle = getSubtle();
  if (!subtle) throw new Error("Este navegador no permite verificar contraseñas en esta conexión (hace falta https).");
  const Encoder = (globalThis as any).TextEncoder;
  const key = await subtle.importKey("raw", new Encoder().encode(password), "PBKDF2", false, ["deriveBits"]);
  const bits = await subtle.deriveBits(
    { name: "PBKDF2", salt: hexToBytes(saltHex), iterations: AUTH_ITERATIONS, hash: "SHA-256" },
    key,
    AUTH_HASH_BYTES * 8
  );
  return bytesToHex(new Uint8Array(bits));
};

/** Comparación de cadenas que no corta en la primera diferencia. */
export const sameHex = (a: string, b: string): boolean => {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
};
