import { OWN_HOURS_SHEETS } from "../config";
import { AccumulatedResult, AgendaResult, ContractsResult, Dataset, HoursResult, OwnHoursResults, TimesResult } from "./types";

/** Asigna a cada equipo con hoja propia la tabla de su hoja (sólo las hojas ya cargadas). */
export const ownHoursByEquipment = (own: OwnHoursResults | null | undefined): Dataset["hoursByEquipment"] => {
  const out: Dataset["hoursByEquipment"] = {};
  if (own) {
    OWN_HOURS_SHEETS.forEach((sheet) => {
      const res = own[sheet.key];
      if (res) out[sheet.equipment] = res.hours;
    });
  }
  return out;
};

/**
 * Arma el Dataset que consumen los cálculos a partir de las hojas ya leídas.
 * `horasPropias` trae las hojas de los equipos con tabla de horas aparte (si no se pasa, todos usan `horas`).
 */
export const buildDataset = (
  horas: HoursResult,
  tiempos: TimesResult,
  acc: AccumulatedResult,
  horasPropias?: OwnHoursResults | null,
  capacidades?: AgendaResult | null,
  contratos?: ContractsResult | null
): Dataset => {
  const studies: Record<string, true> = {};
  tiempos.studyTypes.concat(acc.studyTypes).forEach((s) => {
    studies[s] = true;
  });
  return {
    times: tiempos.times,
    proportions: acc.proportions,
    monthlyQuantities: acc.monthlyQuantities,
    hourlyQuantities: acc.hourlyQuantities,
    actual: acc.actual,
    hours: horas.hours,
    hoursByEquipment: ownHoursByEquipment(horasPropias),
    agenda: capacidades ? capacidades.agenda : {},
    contracts: contratos ? contratos.contracts : {},
    yearlyQuantities: acc.yearlyQuantities,
    maxMonthPerYear: acc.maxMonthPerYear,
    studyTypes: Object.keys(studies).sort(),
    studyHierarchy: tiempos.hierarchy,
    equipments: acc.equipments.slice(),
    years: acc.years.slice(),
  };
};
