import { DEPENDENCY_THRESHOLD } from "../config";
import { Dataset } from "../data/types";
import { ExtraLoad, studyEquipmentMatrix } from "./matrix";
import { CustomTimes } from "./times";

// Dependencia de la red de cada equipo: categorías secundarias de estudios en las que UN solo equipo
// produce más del 50 % (por cantidad de estudios) de lo que hace toda la flota activa.

type Source = Pick<Dataset, "studyTypes" | "studyHierarchy" | "times" | "monthlyQuantities">;

export interface DependencyItem {
  category: string;
  /** Estudios de la categoría entre los equipos activos. */
  total: number;
  /** Equipo que más produce y su cantidad y porcentaje. */
  topEq: string;
  topCount: number;
  topShare: number;
  /** El mayor productor supera el umbral. */
  dependent: boolean;
}

export interface DependencyEquipment {
  eq: string;
  isActive: boolean;
  /** Categorías secundarias donde este equipo supera el umbral, de mayor a menor porcentaje. */
  categories: DependencyItem[];
  /** Estudios del equipo en esas categorías. */
  studiesInDependent: number;
  /** Estudios totales del equipo en el período. */
  studies: number;
  /** studiesInDependent / studies (%), o null sin estudios. */
  shareOfStudies: number | null;
}

export interface DependencySummary {
  /** Todas las categorías secundarias con estudios, las dependientes primero. */
  items: DependencyItem[];
  rows: DependencyEquipment[];
  total: {
    /** Equipos activos que son el equipo dominante de alguna categoría. */
    equipmentsWithDependency: number;
    activeEquipments: number;
    dependentCategories: number;
    categories: number;
    /** Estudios de la flota activa en categorías con dependencia, y su porcentaje del total. */
    studiesInDependent: number;
    studies: number;
    shareOfStudies: number | null;
  };
}

/**
 * Dependencia por equipo en los meses no excluidos de un año. Sólo cuentan los equipos activos (los demás
 * figuran sin cifras); el porcentaje de cada equipo es sobre los estudios de esa categoría entre los activos.
 * `extra` suma estudios reubicados (simulador).
 */
export const dependencySummary = (
  ds: Source,
  custom: CustomTimes,
  opts: { year: number; excluded: Set<string>; equipments: string[]; activeEqs: Set<string>; extra?: ExtraLoad }
): DependencySummary => {
  const active = opts.equipments.filter((e) => opts.activeEqs.has(e));
  const matrix = studyEquipmentMatrix(ds, custom, {
    year: opts.year, rowLevel: "secundaria", metric: "cantidad", excludedMonths: opts.excluded, equipments: active, extra: opts.extra,
  });

  const items: DependencyItem[] = [];
  matrix.rows.forEach((row) => {
    if (!(row.totalRow > 0)) return;
    let topEq = "";
    let topCount = -1;
    active.forEach((eq) => {
      const c = row.eqData[eq].count;
      if (c > topCount) { topCount = c; topEq = eq; }
    });
    const topShare = (topCount / row.totalRow) * 100;
    items.push({ category: row.rowLabel, total: row.totalRow, topEq, topCount, topShare, dependent: topShare > DEPENDENCY_THRESHOLD });
  });
  items.sort((a, b) => (a.dependent === b.dependent ? b.total - a.total : a.dependent ? -1 : 1));

  const rows: DependencyEquipment[] = opts.equipments.map((eq) => {
    const isActive = opts.activeEqs.has(eq);
    const categories = items.filter((i) => i.dependent && i.topEq === eq && isActive).sort((a, b) => b.topShare - a.topShare);
    const studies = isActive ? matrix.rows.reduce((a, r) => a + r.eqData[eq].count, 0) : 0;
    const studiesInDependent = categories.reduce((a, c) => a + c.topCount, 0);
    return { eq, isActive, categories, studiesInDependent, studies, shareOfStudies: studies > 0 ? (studiesInDependent / studies) * 100 : null };
  });

  const dependent = items.filter((i) => i.dependent);
  const totalStudies = matrix.rows.reduce((a, r) => a + r.totalRow, 0);
  const inDependent = dependent.reduce((a, i) => a + i.total, 0);
  return {
    items, rows,
    total: {
      equipmentsWithDependency: rows.filter((r) => r.categories.length > 0).length,
      activeEquipments: active.length,
      dependentCategories: dependent.length,
      categories: items.length,
      studiesInDependent: inDependent,
      studies: totalStudies,
      shareOfStudies: totalStudies > 0 ? (inDependent / totalStudies) * 100 : null,
    },
  };
};
