import { Dataset } from "../data/types";
import { groupKey, GroupingLevel } from "./grouping";
import { catalogMinutes, CustomTimes, groupCustomState, minutesFor } from "./times";

export interface MixRow {
  tipo: string;
  tiempo: number;
  isDefault: boolean;
  proporcion: number;
  sumTimeWeight?: number;
  /** Sólo si se pasan tiempos simulados: tiempo simulado (promedio ponderado en grupos) y estado de la edición. */
  tiempoSimulado?: number;
  edicion?: "none" | "uniform" | "mixed";
  /** Valor único editado cuando todos los estudios del grupo tienen el mismo tiempo simulado. */
  valorEditado?: number;
}

/**
 * Mezcla de estudios de un equipo en un año: proporción de cada estudio (o
 * grupo) y tiempo de catálogo (promedio ponderado en los grupos), de mayor a menor.
 */
export const mixTable = (
  ds: Pick<Dataset, "studyTypes" | "studyHierarchy" | "times" | "proportions">,
  eq: string,
  year: number,
  level: GroupingLevel,
  custom?: CustomTimes
): MixRow[] => {
  const propsYear = (ds.proportions[eq] && ds.proportions[eq][year]) || {};
  const eqTimes = ds.times[eq] || {};
  const raw: MixRow[] = ds.studyTypes.map((tipo) => ({
    tipo,
    tiempo: catalogMinutes(ds, eq, tipo),
    isDefault: eqTimes[tipo] ? eqTimes[tipo].isDefault : true,
    proporcion: propsYear[tipo] || 0,
  }));

  // Estado de edición y tiempo simulado, sólo si se pasan tiempos simulados.
  const withSim = (rows: MixRow[], members: Record<string, string[]>, simWeight: Record<string, number>): MixRow[] => {
    if (!custom) return rows;
    return rows.map((r) => {
      const st = groupCustomState(custom, eq, members[r.tipo]);
      const tiempoSimulado =
        level === "estudio" ? minutesFor(ds, custom, eq, r.tipo) : r.proporcion > 0 ? Math.round(simWeight[r.tipo] / r.proporcion) : 0;
      return { ...r, tiempoSimulado, edicion: st.state, valorEditado: st.value };
    });
  };

  if (level === "estudio") {
    const members: Record<string, string[]> = {};
    raw.forEach((r) => {
      members[r.tipo] = [r.tipo];
    });
    return withSim(raw.sort((a, b) => b.proporcion - a.proporcion), members, {});
  }

  const grouped: Record<string, MixRow & { sumTimeWeight: number }> = {};
  const members: Record<string, string[]> = {};
  const simWeight: Record<string, number> = {};
  raw.forEach((row) => {
    const key = groupKey(ds.studyHierarchy, row.tipo, level);
    if (!grouped[key]) {
      grouped[key] = { tipo: key, tiempo: 0, proporcion: 0, sumTimeWeight: 0, isDefault: true };
      members[key] = [];
      simWeight[key] = 0;
    }
    grouped[key].proporcion += row.proporcion;
    grouped[key].sumTimeWeight += row.proporcion * row.tiempo;
    members[key].push(row.tipo);
    if (custom) simWeight[key] += row.proporcion * minutesFor(ds, custom, eq, row.tipo);
    if (!row.isDefault) grouped[key].isDefault = false;
  });
  const rows = Object.keys(grouped)
    .map((k) => {
      const g = grouped[k];
      return { ...g, tiempo: g.proporcion > 0 ? Math.round(g.sumTimeWeight / g.proporcion) : 0 };
    })
    .sort((a, b) => b.proporcion - a.proporcion);
  return withSim(rows, members, simWeight);
};

/** Proporciones de un equipo agrupadas por nivel (para el gráfico de dona). */
export const donutData = (
  ds: Pick<Dataset, "studyHierarchy" | "proportions">,
  eq: string,
  year: number,
  level: GroupingLevel
): { name: string; value: number }[] => {
  const props = (ds.proportions[eq] && ds.proportions[eq][year]) || {};
  const grouped: Record<string, number> = {};
  Object.keys(props).forEach((st) => {
    const key = groupKey(ds.studyHierarchy, st, level);
    grouped[key] = (grouped[key] || 0) + props[st];
  });
  return Object.keys(grouped)
    .filter((k) => grouped[k] > 0)
    .map((k) => ({ name: k, value: grouped[k] * 100 }))
    .sort((a, b) => b.value - a.value);
};
