import { UTILIZATION_THRESHOLDS } from "../config";

/** Colores del semáforo de utilización (criterio institucional, ver config). */
export const SEMAFORO_COLORS = {
  low: "#ef4444", // < 60 %
  mid: "#f59e0b", // 60 - 75 %
  good: "#10b981", // 75 - 90 %
  high: "#4f46e5", // >= 90 %
};

export type SemaforoLevel = "low" | "mid" | "good" | "high";

export const semaforoLevel = (util: number): SemaforoLevel => {
  if (util >= UTILIZATION_THRESHOLDS.high) return "high";
  if (util >= UTILIZATION_THRESHOLDS.mid) return "good";
  if (util >= UTILIZATION_THRESHOLDS.low) return "mid";
  return "low";
};

export const utilizationColor = (util: number): string => SEMAFORO_COLORS[semaforoLevel(util)];
