import React from "react";
import { Clock, Eye, EyeOff } from "lucide-react";
import { Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, Area, ComposedChart, Bar, Cell } from "recharts";
import { MONTH_NAMES } from "../config";
import { CollapsibleSection } from "../components/CollapsibleSection";
import { useModel } from "../model/ModelContext";

export const CapacitySection: React.FC = () => {
  const { excludedMonthsCap, showSimulationCurve, setShowSimulationCurve, toggleMonthCap, chartData, isSimulating } = useModel();

  return (
    <>
      {/* GRÁFICO DE HORAS TRABAJADAS (AHORA PRIMER GRÁFICO VISIBLE) */}
      <CollapsibleSection title="Capacidad vs Produccion Real Estimada (Horas Trabajadas)" subtitle="Compara la carga horaria operativa real frente a las horas hábiles disponibles." icon={<Clock className="text-emerald-600" size={24}/>} defaultOpen={true}>
        <div className="bg-white border border-gray-100 rounded-xl p-6 shadow-sm flex flex-col">
            <div className="flex flex-wrap items-center justify-between gap-4 mb-6">
              {isSimulating && (
                <button onClick={() => setShowSimulationCurve(!showSimulationCurve)} className={`text-xs font-bold px-3 py-1.5 rounded flex items-center gap-2 border transition-colors ${showSimulationCurve ? 'bg-purple-50 text-purple-700 border-purple-200 hover:bg-purple-100' : 'bg-gray-100 text-gray-500 border-gray-300 hover:bg-gray-200'}`}>
                  {showSimulationCurve ? <EyeOff size={14}/> : <Eye size={14}/>} {showSimulationCurve ? 'Ocultar Curva Simulada' : 'Mostrar Curva Simulada'}
                </button>
              )}
              <div className="flex gap-1 flex-wrap ml-auto">
                {MONTH_NAMES.map(m => (
                  <button key={m} onClick={() => toggleMonthCap(m)} className={`px-2 py-1 text-[10px] font-bold rounded border ${!excludedMonthsCap.has(m) ? 'bg-white border-gray-300' : 'bg-gray-200 text-gray-400'}`}>{m.substring(0, 3)}</button>
                ))}
              </div>
            </div>
            <div className="w-full h-[400px]">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} />
                  <XAxis dataKey="mes" tick={{fontSize: 12}} />
                  <YAxis yAxisId="left" tick={{fontSize: 12}} label={{ value: 'Horas', angle: -90, position: 'insideLeft', offset: 15 }}/>
                  <YAxis yAxisId="right" orientation="right" tickFormatter={v => `${v}%`} tick={{fontSize: 12}} domain={[0, (dataMax: number) => Math.max(100, Math.ceil(dataMax / 10) * 10)]} />
                  <Tooltip 
                    contentStyle={{borderRadius: '12px'}} 
                    formatter={(value: any, name: any, props: any) => {
                       if (typeof value === 'number') {
                         if (name.includes('Utilización')) return [`${value.toFixed(2)}%`, name];
                         if (name === 'Horas Trabajadas (Real)' || name === 'Horas Trabajadas (Simuladas)') {
                            const estOrig = props.payload.EstudiosOriginales;
                            return [`${value.toFixed(1)} hs (Abarca ${estOrig} estudios)`, name];
                         }
                         return [Number.isInteger(value) ? value : value.toFixed(1), name];
                       }
                       return [value, name];
                    }}
                  />
                  <Legend />

                  <Area yAxisId="left" type="monotone" dataKey="HorasHabiles" fill="#EFF6FF" stroke="#3B82F6" strokeWidth={2} strokeDasharray="5 5" name="Horas Hábiles Disp." />

                  {isSimulating && showSimulationCurve && <Line yAxisId="left" type="monotone" dataKey="HorasTrabajadasSimuladas" stroke="#8B5CF6" strokeWidth={4} strokeDasharray="5 5" name="Horas Trabajadas (Simuladas)" />}

                  <Bar yAxisId="left" dataKey="HorasTrabajadasOriginal" barSize={30} name="Horas Trabajadas (Real)" fill="#10B981">
                    {chartData.map((e, i) => <Cell key={i} fill={e.isExcluded ? '#D1D5DB' : '#10B981'} />)}
                  </Bar>

                  <Line yAxisId="right" type="monotone" dataKey="UtilizacionHoras" stroke="#F59E0B" strokeWidth={3} name="Utilización [%]" />
                  {isSimulating && showSimulationCurve && <Line yAxisId="right" type="monotone" dataKey="UtilizacionHorasSimulada" stroke="#D946EF" strokeWidth={3} strokeDasharray="3 3" name="Utilización Simulada [%]" />}

                </ComposedChart>
              </ResponsiveContainer>
            </div>
        </div>
      </CollapsibleSection>
    </>
  );
};
