import React, { useState } from "react";
import { Activity, AlertCircle, Eye, EyeOff, Settings } from "lucide-react";
import { useAuth } from "../auth/AuthContext";

/** Pantalla de ingreso: pide usuario y contraseña antes de mostrar el tablero. */
export const LoginScreen: React.FC = () => {
  const { login } = useAuth();
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      const result = await login(username, password);
      if (!result.ok) {
        setError(result.error || "No se pudo ingresar.");
        setBusy(false);
      }
      // si salió bien, el tablero reemplaza esta pantalla
    } catch (err) {
      setError(err instanceof Error ? err.message : "No se pudo ingresar.");
      setBusy(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6 text-gray-800 font-sans flex items-center justify-center">
      <div className="w-full max-w-sm bg-white rounded-2xl shadow-sm border border-gray-200 p-8">
        <h1 className="text-2xl font-bold flex items-center gap-2 text-gray-900">
          <Activity className="text-blue-600" /> Simulador de Productividad
        </h1>
        <p className="text-sm text-gray-500 mt-2">Ingresá con tu usuario y contraseña para ver el tablero. Los datos se cargan automáticamente al ingresar.</p>

        <form onSubmit={submit} className="mt-6 space-y-4">
          <div>
            <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1" htmlFor="login-usuario">Usuario</label>
            <input
              id="login-usuario"
              type="text"
              autoComplete="username"
              autoFocus
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full bg-gray-50 border border-gray-300 text-sm rounded-lg p-2 font-bold outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1" htmlFor="login-clave">Contraseña</label>
            <div className="relative">
              <input
                id="login-clave"
                type={showPassword ? "text" : "password"}
                autoComplete="current-password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full bg-gray-50 border border-gray-300 text-sm rounded-lg p-2 pr-10 font-bold outline-none focus:ring-2 focus:ring-blue-500"
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                title={showPassword ? "Ocultar la contraseña" : "Mostrar la contraseña"}
                className="absolute inset-y-0 right-0 px-3 text-gray-400 hover:text-gray-700"
              >
                {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
              </button>
            </div>
          </div>

          {error && <p className="text-xs text-red-600 font-bold flex items-center gap-1"><AlertCircle size={12} /> {error}</p>}

          <button
            type="submit"
            disabled={busy || username.trim() === "" || password === ""}
            className="w-full bg-blue-600 text-white px-5 py-2.5 rounded-xl font-bold text-sm hover:bg-blue-700 disabled:opacity-50 flex items-center justify-center gap-2 shadow-sm transition-colors"
          >
            {busy && <Settings className="animate-spin" size={16} />} Ingresar
          </button>
        </form>

        <p className="text-[11px] text-gray-400 mt-6">Versión preliminar para revisión.</p>
      </div>
    </div>
  );
};
