import React from "react";
import { AlertCircle, X, PieChart as PieChartIcon } from "lucide-react";
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from "recharts";
import { PIE_COLORS } from "../constants";
import { useModel } from "../model/ModelContext";

export const Modals: React.FC = () => {
  const { activeTab, selectedYear, groupingLevel, showDonutModalEq, setShowDonutModalEq, cellDetails, setCellDetails, drillDownModal, setDrillDownModal, simulationYear, donutData } = useModel();

  return (
    <>
      {/* --- MODALES COMPARTIDOS --- */}

      {/* 1. DRILL-DOWN (GRÁFICO DE DONA) */}
      {drillDownModal && (
        <div className="fixed inset-0 z-[120] bg-gray-900/70 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="bg-gray-800 px-6 py-4 flex justify-between items-center">
              <h3 className="text-lg font-bold text-white flex items-center gap-2">
                <PieChartIcon size={20} className="text-blue-400" /> {drillDownModal.title}
              </h3>
              <button onClick={() => setDrillDownModal(null)} className="text-gray-400 hover:text-white transition-colors p-1 bg-gray-700/50 rounded-lg"><X size={20} /></button>
            </div>
            <div className="bg-gray-100 px-6 py-2 border-b border-gray-200 text-xs font-bold text-gray-500 uppercase tracking-wider">
               {drillDownModal.subtitle}
            </div>
            <div className="p-6">
              {drillDownModal.data.length === 0 ? (
                <div className="text-center p-12 text-gray-500">
                  <AlertCircle size={40} className="mx-auto mb-3 text-gray-300" />
                  <p>No hay datos registrados en este nivel.</p>
                </div>
              ) : (
                <div className="flex flex-col md:flex-row items-center h-[400px]">
                  <div className="w-full md:w-1/2 h-full">
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie data={drillDownModal.data} cx="50%" cy="50%" innerRadius={90} outerRadius={140} paddingAngle={2} dataKey="value">
                          {drillDownModal.data.map((e, i) => <Cell key={`cell-${i}`} fill={PIE_COLORS[i % PIE_COLORS.length]} />)}
                        </Pie>
                        <Tooltip formatter={(value: any) => [value, 'Estudios']} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
                      </PieChart>
                    </ResponsiveContainer>
                  </div>
                  <div className="w-full md:w-1/2 h-full overflow-y-auto pr-2 pl-4 py-2 custom-scrollbar">
                    <h4 className="font-bold text-gray-800 border-b border-gray-200 pb-2 mb-3">Distribución de Estudios</h4>
                    <div className="space-y-2">
                      {drillDownModal.data.map((entry, index) => {
                         const totalDrill = drillDownModal.data.reduce((sum, e) => sum + e.value, 0);
                         const pct = (entry.value / totalDrill) * 100;
                         return (
                           <div key={index} className="flex items-center justify-between bg-gray-50 px-3 py-2 rounded-lg border border-gray-100">
                             <div className="flex items-center gap-2 overflow-hidden">
                               <div className="w-3 h-3 rounded-full shrink-0" style={{ backgroundColor: PIE_COLORS[index % PIE_COLORS.length] }}></div>
                               <span className="text-xs font-medium text-gray-700 truncate" title={entry.name}>{entry.name}</span>
                             </div>
                             <div className="flex items-center gap-3 shrink-0 ml-2">
                               <span className="text-xs font-bold text-gray-600">{entry.value}</span>
                               <span className="text-xs font-black text-blue-600 w-12 text-right">{pct.toFixed(1)}%</span>
                             </div>
                           </div>
                         );
                      })}
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* 2. CELDAS DE MAPA (CLICK) */}
      {cellDetails && activeTab !== 'simulacion' && (
        <div className="fixed inset-0 z-[110] bg-gray-900/60 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-in zoom-in-95 duration-200 border border-gray-200">
            <div className="bg-gray-800 px-5 py-4 flex justify-between items-center">
              <div>
                <h3 className="text-base font-bold text-white leading-tight">{cellDetails.eq}</h3>
                <p className="text-gray-400 text-xs mt-0.5">{cellDetails.mes} {selectedYear}</p>
              </div>
              <button onClick={() => setCellDetails(null)} className="text-gray-400 hover:text-white p-1 bg-gray-700/50 rounded-lg"><X size={18} /></button>
            </div>
            <div className="p-5 space-y-4 bg-gray-50">
              <div className="flex justify-between items-center bg-white p-3 rounded-xl border border-gray-200 shadow-sm">
                <span className="text-xs font-bold text-gray-500 uppercase">Estudios Realizados</span>
                <span className="text-lg font-black text-gray-800">{cellDetails.count}</span>
              </div>
              <div className="flex justify-between items-center bg-white p-3 rounded-xl border border-gray-200 shadow-sm">
                <span className="text-xs font-bold text-gray-500 uppercase">Horas Trabajadas</span>
                <span className="text-lg font-black text-blue-600">{cellDetails.usedHours.toFixed(1)} hs</span>
              </div>
              <div className="flex justify-between items-center bg-white p-3 rounded-xl border border-gray-200 shadow-sm">
                <span className="text-xs font-bold text-gray-500 uppercase">Horas Hábiles Disp.</span>
                <span className="text-lg font-black text-emerald-600">{cellDetails.availHours} hs</span>
              </div>
              <div className="flex justify-between items-center p-4 rounded-xl border border-gray-200 shadow-inner bg-gray-800 text-white mt-2">
                <span className="text-sm font-bold uppercase">Utilización Total</span>
                <span className={`text-2xl font-black ${cellDetails.util >= 90 ? 'text-indigo-400' : cellDetails.util >= 75 ? 'text-emerald-400' : cellDetails.util >= 60 ? 'text-amber-400' : 'text-red-400'}`}>
                  {cellDetails.util.toFixed(1)}%
                </span>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 3. CELDAS SIMULADOR (CLICK) */}
      {cellDetails && activeTab === 'simulacion' && (
        <div className="fixed inset-0 z-[110] bg-gray-900/60 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-in zoom-in-95 duration-200 border border-gray-200">
            <div className="bg-gray-800 px-5 py-4 flex justify-between items-center">
              <div>
                <h3 className="text-base font-bold text-white leading-tight">{cellDetails.eq} <span className="text-[10px] bg-orange-500 text-white px-1.5 py-0.5 rounded ml-2 align-middle">SIMULADO</span></h3>
                <p className="text-gray-400 text-xs mt-0.5">{cellDetails.mes} {simulationYear}</p>
              </div>
              <button onClick={() => setCellDetails(null)} className="text-gray-400 hover:text-white p-1 bg-gray-700/50 rounded-lg"><X size={18} /></button>
            </div>
            <div className="p-5 space-y-4 bg-gray-50">
              <div className="flex justify-between items-center bg-white p-3 rounded-xl border border-gray-200 shadow-sm">
                <span className="text-xs font-bold text-gray-500 uppercase">Estudios Totales</span>
                <span className="text-lg font-black text-gray-800">{cellDetails.count.toFixed(0)}</span>
              </div>
              <div className="flex justify-between items-center bg-white p-3 rounded-xl border border-gray-200 shadow-sm">
                <span className="text-xs font-bold text-gray-500 uppercase">Horas Requeridas</span>
                <span className="text-lg font-black text-orange-600">{cellDetails.usedHours.toFixed(1)} hs</span>
              </div>
              <div className="flex justify-between items-center bg-white p-3 rounded-xl border border-gray-200 shadow-sm">
                <span className="text-xs font-bold text-gray-500 uppercase">Horas Hábiles Disp.</span>
                <span className="text-lg font-black text-emerald-600">{cellDetails.availHours} hs</span>
              </div>
              <div className="flex justify-between items-center p-4 rounded-xl border border-gray-200 shadow-inner bg-gray-800 text-white mt-2">
                <span className="text-sm font-bold uppercase">Nueva Utilización</span>
                <span className={`text-2xl font-black ${cellDetails.util >= 90 ? 'text-indigo-400' : cellDetails.util >= 75 ? 'text-emerald-400' : cellDetails.util >= 60 ? 'text-amber-400' : 'text-red-400'}`}>
                  {cellDetails.util.toFixed(1)}%
                </span>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 4. MODAL MIX DONA EQUIPO */}
      {showDonutModalEq && (
        <div className="fixed inset-0 z-[100] bg-gray-900/60 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="bg-gray-800 px-6 py-4 flex justify-between items-center">
              <h3 className="text-lg font-bold text-white flex items-center gap-2">
                <PieChartIcon size={20} className="text-blue-400" /> Mix de Estudios ({selectedYear}) - {showDonutModalEq}
              </h3>
              <button onClick={() => setShowDonutModalEq(null)} className="text-gray-400 hover:text-white transition-colors p-1 bg-gray-700/50 rounded-lg"><X size={20} /></button>
            </div>
            <div className="p-6">
              {donutData.length === 0 ? (
                <div className="text-center p-12 text-gray-500">
                  <AlertCircle size={40} className="mx-auto mb-3 text-gray-300" />
                  <p>No hay datos de mix de estudios registrados para este equipo en {selectedYear}.</p>
                </div>
              ) : (
                <div className="flex flex-col md:flex-row items-center h-[400px]">
                  <div className="w-full md:w-1/2 h-full">
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie data={donutData} cx="50%" cy="50%" innerRadius={90} outerRadius={140} paddingAngle={2} dataKey="value">
                          {donutData.map((e, i) => <Cell key={`cell-${i}`} fill={PIE_COLORS[i % PIE_COLORS.length]} />)}
                        </Pie>
                        <Tooltip formatter={(value: any) => [`${Number(value).toFixed(2)}%`, 'Proporción']} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
                      </PieChart>
                    </ResponsiveContainer>
                  </div>
                  <div className="w-full md:w-1/2 h-full overflow-y-auto pr-2 pl-4 py-2 custom-scrollbar">
                    <h4 className="font-bold text-gray-800 border-b border-gray-200 pb-2 mb-3">
                      Distribución del {selectedYear} ({groupingLevel === 'principal' ? 'Categoría Principal' : groupingLevel === 'secundaria' ? 'Categoría Secundaria' : groupingLevel === 'todo' ? 'General' : 'Estudio'})
                    </h4>
                    <div className="space-y-2">
                      {donutData.map((entry, index) => (
                        <div key={index} className="flex items-center justify-between bg-gray-50 px-3 py-2 rounded-lg border border-gray-100">
                          <div className="flex items-center gap-2 overflow-hidden">
                            <div className="w-3 h-3 rounded-full shrink-0" style={{ backgroundColor: PIE_COLORS[index % PIE_COLORS.length] }}></div>
                            <span className="text-xs font-medium text-gray-700 truncate">{entry.name}</span>
                          </div>
                          <span className="text-xs font-bold text-gray-900 shrink-0 ml-2">{entry.value.toFixed(2)}%</span>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

    </>
  );
};
