import { Dataset } from "../data/types";
import { ExtraLoad } from "./matrix";
import { groupKey, GroupingLevel } from "./grouping";

export const nextLevel = (level: GroupingLevel): GroupingLevel | null => {
  if (level === "estudio") return null;
  return level === "todo" ? "principal" : level === "principal" ? "secundaria" : "estudio";
};

/**
 * Desglose de una categoría de un equipo en el nivel siguiente. `extra` suma
 * la carga reubicada (simulador) para que el desglose coincida con la celda.
 */
export const drillDown = (
  ds: Pick<Dataset, "monthlyQuantities" | "studyHierarchy">,
  opts: {
    eq: string;
    year: number;
    category: string;
    level: GroupingLevel;
    months: string[];
    extra?: ExtraLoad;
  }
): { name: string; value: number }[] => {
  const next = nextLevel(opts.level);
  if (!next) return [];
  const counts: Record<string, number> = {};
  const add = (st: string, qty: number) => {
    if (opts.level === "todo" || groupKey(ds.studyHierarchy, st, opts.level) === opts.category) {
      const child = groupKey(ds.studyHierarchy, st, next);
      counts[child] = (counts[child] || 0) + qty;
    }
  };
  opts.months.forEach((m) => {
    const mq = (ds.monthlyQuantities[opts.eq] && ds.monthlyQuantities[opts.eq][opts.year] && ds.monthlyQuantities[opts.eq][opts.year][m]) || {};
    Object.keys(mq).forEach((st) => add(st, mq[st]));
    const ex = opts.extra && opts.extra[opts.eq] ? opts.extra[opts.eq][m] : undefined;
    if (ex) Object.keys(ex).forEach((st) => add(st, ex[st]));
  });
  return Object.keys(counts)
    .filter((k) => counts[k] > 0)
    .map((k) => ({ name: k, value: counts[k] }))
    .sort((a, b) => b.value - a.value);
};
