import { MONTH_NAMES } from "../config";
import {
  cleanText,
  headersOf,
  IssueCollector,
  parseDateParts,
  parseHour,
  resolveColumn,
  toIsoDate,
} from "./normalize";
import { AccumulatedResult, StudyCounts } from "./types";

type Row = Record<string, unknown>;

/**
 * Hoja ACUMULADO_ESTUDIOS_CURADO: una fila por estudio realizado
 * (Fecha, Hora_ingreso, Equipo, Estudio). Agrega por equipo/año/mes/estudio
 * y arma el mapa horario (día de semana + hora).
 */
export const parseAcumulado = (rows: Row[]): AccumulatedResult => {
  const issues = new IssueCollector("ACUMULADO");
  const actual: AccumulatedResult["actual"] = {};
  const yearly: AccumulatedResult["yearlyQuantities"] = {};
  const monthly: AccumulatedResult["monthlyQuantities"] = {};
  const hourly: AccumulatedResult["hourlyQuantities"] = {};
  const maxMonth: Record<number, number> = {};
  const equipments: Record<string, true> = {};
  const years: Record<number, true> = {};
  const studies: Record<string, true> = {};

  const headers = headersOf(rows);
  const dateCol = resolveColumn(headers, ["Fecha"]);
  const hourCol = resolveColumn(headers, ["Hora_ingreso", "Hora"]);
  const eqCol = resolveColumn(headers, ["Equipo"]);
  const studyCol = resolveColumn(headers, ["Estudio"]);

  const empty = (): AccumulatedResult => ({
    actual, yearlyQuantities: yearly, monthlyQuantities: monthly, hourlyQuantities: hourly,
    proportions: {}, maxMonthPerYear: maxMonth, equipments: [], years: [], studyTypes: [],
    stats: { totalRows: rows.length, validRows: 0, discardedRows: rows.length, minDate: null, maxDate: null, rowsWithoutHour: 0 },
    issues: issues.toArray(),
  });

  const missing: string[] = [];
  if (!dateCol) missing.push("Fecha");
  if (!eqCol) missing.push("Equipo");
  if (!studyCol) missing.push("Estudio");
  if (missing.length > 0) {
    issues.add("acc-missing-columns", "error", `Faltan columnas obligatorias en el acumulado: ${missing.join(", ")}.`);
    return empty();
  }
  if (!hourCol) {
    issues.add("acc-no-hour-column", "warning", 'No se encontró la columna "Hora_ingreso": no se podrá armar el mapa horario.');
  }

  let valid = 0;
  let withoutHour = 0;
  let minTs = Infinity;
  let maxTs = -Infinity;
  let minIso: string | null = null;
  let maxIso: string | null = null;

  rows.forEach((row, i) => {
    const equipo = cleanText(row[eqCol as string]);
    const estudio = cleanText(row[studyCol as string]);
    const rawDate = row[dateCol as string];
    const fila = `fila ${i + 2}`;

    if (equipo === "" || estudio === "" || cleanText(rawDate) === "") {
      issues.add("acc-incomplete-row", "warning", "Filas descartadas por no tener fecha, equipo o estudio.", fila);
      return;
    }
    const date = parseDateParts(typeof rawDate === "string" ? rawDate : cleanText(rawDate));
    if (!date) {
      issues.add("acc-invalid-date", "warning", "Filas descartadas por fecha inválida.", `${fila}: "${cleanText(rawDate)}"`);
      return;
    }

    valid++;
    const { year, month, day } = date;
    const mes = MONTH_NAMES[month - 1];
    const dayOfWeek = new Date(year, month - 1, day).getDay();

    const ts = year * 10000 + month * 100 + day;
    if (ts < minTs) { minTs = ts; minIso = toIsoDate(date); }
    if (ts > maxTs) { maxTs = ts; maxIso = toIsoDate(date); }

    if (!maxMonth[year] || month > maxMonth[year]) maxMonth[year] = month;
    equipments[equipo] = true;
    years[year] = true;
    studies[estudio] = true;

    if (!actual[equipo]) actual[equipo] = {};
    if (!actual[equipo][year]) actual[equipo][year] = {};
    actual[equipo][year][mes] = (actual[equipo][year][mes] || 0) + 1;

    if (!yearly[equipo]) yearly[equipo] = {};
    if (!yearly[equipo][year]) yearly[equipo][year] = {};
    yearly[equipo][year][estudio] = (yearly[equipo][year][estudio] || 0) + 1;

    if (!monthly[equipo]) monthly[equipo] = {};
    if (!monthly[equipo][year]) monthly[equipo][year] = {};
    if (!monthly[equipo][year][mes]) monthly[equipo][year][mes] = {};
    monthly[equipo][year][mes][estudio] = (monthly[equipo][year][mes][estudio] || 0) + 1;

    if (!hourly[equipo]) hourly[equipo] = {};
    if (!hourly[equipo][year]) hourly[equipo][year] = {};
    if (!hourly[equipo][year][mes]) hourly[equipo][year][mes] = {};
    if (!hourly[equipo][year][mes][dayOfWeek]) hourly[equipo][year][mes][dayOfWeek] = {};

    const hour = hourCol ? parseHour(row[hourCol]) : null;
    if (hour === null) {
      withoutHour++;
      if (hourCol) {
        issues.add("acc-invalid-hour", "info", "Estudios sin hora interpretable (cuentan en los totales pero no en el mapa horario).", `${fila}: "${cleanText(row[hourCol])}"`);
      }
    } else {
      const byHour = hourly[equipo][year][mes][dayOfWeek];
      if (!byHour[hour]) byHour[hour] = {};
      byHour[hour][estudio] = (byHour[hour][estudio] || 0) + 1;
    }
  });

  // Proporción de cada estudio dentro del total anual del equipo.
  const proportions: AccumulatedResult["proportions"] = {};
  Object.keys(yearly).forEach((eq) => {
    proportions[eq] = {};
    Object.keys(yearly[eq]).forEach((yrStr) => {
      const yr = parseInt(yrStr, 10);
      const counts: StudyCounts = yearly[eq][yr];
      let total = 0;
      Object.keys(counts).forEach((k) => { total += counts[k]; });
      proportions[eq][yr] = {};
      Object.keys(counts).forEach((k) => {
        proportions[eq][yr][k] = total > 0 ? counts[k] / total : 0;
      });
    });
  });

  if (rows.length > 0 && valid === 0) {
    issues.add("acc-no-valid-rows", "error", "Ninguna fila del acumulado pudo interpretarse.");
  }

  return {
    actual,
    yearlyQuantities: yearly,
    monthlyQuantities: monthly,
    hourlyQuantities: hourly,
    proportions,
    maxMonthPerYear: maxMonth,
    equipments: Object.keys(equipments).sort(),
    years: Object.keys(years).map(Number).sort((a, b) => a - b),
    studyTypes: Object.keys(studies).sort(),
    stats: {
      totalRows: rows.length,
      validRows: valid,
      discardedRows: rows.length - valid,
      minDate: minIso,
      maxDate: maxIso,
      rowsWithoutHour: withoutHour,
    },
    issues: issues.toArray(),
  };
};
