import { MONTH_NAMES } from "../config";

/** Cantidad de veces que cae un día de la semana (0=dom..6=sáb) en un mes (monthIndex 0-11). */
export const getWeekdaysInMonth = (year: number, monthIndex: number, dayOfWeek: number): number => {
  let count = 0;
  const d = new Date(year, monthIndex, 1);
  while (d.getDay() !== dayOfWeek) d.setDate(d.getDate() + 1);
  while (d.getMonth() === monthIndex) {
    count++;
    d.setDate(d.getDate() + 7);
  }
  return count;
};

/**
 * Meses sin datos de un año: todos los posteriores al último mes con datos.
 * (Los datos de un mes se cargan con el mes terminado.)
 */
export const monthsWithoutData = (maxMonthPerYear: Record<number, number>, year: number): Set<string> => {
  const maxMonth = year ? maxMonthPerYear[year] : undefined;
  const out = new Set<string>();
  if (!maxMonth) return out;
  MONTH_NAMES.forEach((m, idx) => {
    if (idx + 1 > maxMonth) out.add(m);
  });
  return out;
};

/**
 * Texto corto para un conjunto de meses: "Enero – Julio" si son consecutivos,
 * "Ene, Mar, Abr" si hay huecos (así no se confunde "Enero – Julio" con un período completo).
 */
export const describeMonths = (months: string[]): string => {
  const idx = MONTH_NAMES.map((m, i) => (months.indexOf(m) !== -1 ? i : -1)).filter((i) => i !== -1);
  if (idx.length === 0) return "";
  if (idx.length === 1) return MONTH_NAMES[idx[0]];
  const consecutive = idx[idx.length - 1] - idx[0] === idx.length - 1;
  if (consecutive) return `${MONTH_NAMES[idx[0]]} – ${MONTH_NAMES[idx[idx.length - 1]]}`;
  return idx.map((i) => MONTH_NAMES[i].substring(0, 3)).join(", ");
};
