import React, { useState } from "react";
import { AlertTriangle, BarChart2, Briefcase, Calendar } from "lucide-react";
import { DEPENDENCY_THRESHOLD, TARGET_UTILIZATION } from "../config";
import * as calc from "../calc";
import { AgendaCompositionModal } from "../components/AgendaCompositionModal";
import { FleetTable } from "../components/FleetTable";
import { FxRateControl } from "../components/FxRateControl";
import { KpiBanner, KpiMetric } from "../components/KpiBanner";
import type { MonthlyDetailRequest } from "../components/MonthlyDetailModal";
import { useAuth } from "../auth/AuthContext";
import { useModel } from "../model/ModelContext";
import { ProductivityChartSection } from "./ProductivityChartSection";

type BannerId = 'agenda' | 'productividad' | 'costos' | 'dependencia';

const formatCount = (n: number) => n.toLocaleString('es-AR', { maximumFractionDigits: 0 });
const formatUsd = (n: number, decimals: number = 0) => `USD ${n.toLocaleString('es-AR', { minimumFractionDigits: decimals, maximumFractionDigits: decimals })}`;
const NA = <span className="text-gray-300">—</span>;
const sign = (n: number) => (n > 0 ? '+' : n < 0 ? '−' : '');

const colored = (value: number | null, text: string) =>
  value === null ? NA : <span style={{ color: calc.utilizationColor(value) }}>{text}</span>;

// Diferencias contra la flota actual (solo en el escenario simulado): una etiqueta destacada con flecha y, en chico,
// el valor original. Verde = la variación va en el sentido favorable; amarillo = en sentido contrario (para cada
// métrica `goodWhenUp` dice si subir es favorable). Sin diferencia no se muestra la etiqueta.
const pill = (diff: number, text: string, goodWhenUp: boolean): React.ReactNode => {
  const favorable = (diff > 0) === goodWhenUp;
  const color = favorable ? 'bg-emerald-100 text-emerald-700 border-emerald-300' : 'bg-amber-100 text-amber-800 border-amber-300';
  return (
    <span title={favorable ? 'Variación favorable respecto de la flota actual' : 'Variación desfavorable respecto de la flota actual'} className={`inline-flex items-center gap-1 border rounded-md px-2 py-0.5 text-xs font-black ${color}`}>
      {diff > 0 ? '▲' : '▼'} {text}
    </span>
  );
};
const diffPct = (now: number | null, before: number | null | undefined, goodWhenUp: boolean = true): React.ReactNode =>
  now === null || before === null || before === undefined || Math.abs(now - before) < 0.05 ? null : pill(now - before, `${sign(now - before)}${Math.abs(now - before).toFixed(1)} %`, goodWhenUp);
const diffNum = (now: number | null, before: number | null | undefined, unit: string = '', goodWhenUp: boolean = true): React.ReactNode =>
  now === null || before === null || before === undefined || Math.abs(now - before) < 0.5 ? null : pill(now - before, `${sign(now - before)}${formatCount(Math.abs(now - before))}${unit ? ` ${unit}` : ''}`, goodWhenUp);
const diffUsd = (now: number | null, before: number | null | undefined, decimals: number = 0, goodWhenUp: boolean = true): React.ReactNode =>
  now === null || before === null || before === undefined || Math.abs(now - before) < Math.pow(10, -decimals) / 2 ? null
    : pill(now - before, `${sign(now - before)}${formatUsd(Math.abs(now - before), decimals)}`, goodWhenUp);
/** Valor original (flota actual) en chico; solo en el escenario simulado. */
const was = (before: number | null | undefined, format: (n: number) => string): string | null =>
  before === null || before === undefined ? null : `Actual: ${format(before)}`;
const fmtPct = (n: number) => `${n.toFixed(1)}%`;
const fmtH = (n: number) => `${formatCount(n)} h`;
const fmtSigned = (n: number) => `${Math.round(n) > 0 ? '+' : ''}${formatCount(n)}`;

/** Varias líneas chicas bajo un valor (se omiten las vacías). */
const lines = (...items: Array<React.ReactNode | null | undefined | false>): React.ReactNode => {
  const shown = items.filter(Boolean);
  return shown.length === 0 ? undefined : <>{shown.map((x, i) => <div key={i}>{x}</div>)}</>;
};

export interface SummaryPanelProps {
  /** true = escenario simulado (muestra la diferencia contra la flota actual). */
  scenario: boolean;
  year: number;
  /** Meses considerados. */
  monthsCount: number;
  period: string;
  /** Equipos a mostrar y total de la flota (en el escenario, solo los que siguen operando). */
  fleet: calc.FleetSummary;
  baselineFleet?: calc.FleetSummary;
  agenda: calc.AgendaSummary | null;
  agendaBaseline?: calc.AgendaSummary | null;
  contracts: calc.ContractSummary | null;
  contractsBaseline?: calc.ContractSummary | null;
  dependency: calc.DependencySummary | null;
  dependencyBaseline?: calc.DependencySummary | null;
  /** Equipos fuera de servicio en el escenario. */
  removed?: string[];
  onToggleEq?: (eq: string) => void;
  /** Selector de equipos arriba de los banners: todos los equipos, los que se consideran y cómo volver a todos. */
  picker?: { equipments: string[]; selected: Set<string>; onAll: () => void };
  onDetail: (request: MonthlyDetailRequest) => void;
  /** Gráfico mensual de productividad en el banner de productividad. */
  showChart: boolean;
}

/**
 * Cuatro banners con las cifras del total de la flota (agenda, productividad, costos y dependencia); al hacer
 * clic en uno se despliega el detalle por equipo. Sirve para la flota actual y para el escenario simulado.
 */
export const SummaryPanel: React.FC<SummaryPanelProps> = ({
  scenario, year, monthsCount, period, fleet, baselineFleet, agenda, agendaBaseline, contracts, contractsBaseline,
  dependency, dependencyBaseline, removed, onToggleEq, picker, onDetail, showChart,
}) => {
  const { usingSimulatedTimes, fx, fxStatus, setFxManual } = useModel();
  const [open, setOpen] = useState<BannerId | null>('productividad');
  // Ventana de distribución por categoría de la agenda: undefined = cerrada, null = total de la flota
  const [agendaDetail, setAgendaDetail] = useState<string | null | undefined>(undefined);

  const toggle = (id: BannerId) => setOpen(open === id ? null : id);
  const wording = calc.periodWording(monthsCount, year);
  const utilLabel = scenario ? wording.simUtil : wording.util;
  const totalLabel = scenario ? 'Total Flota Simulada' : 'Total Flota Activa';
  const total = fleet.total;
  const base = baselineFleet ? baselineFleet.total : undefined;
  const hasArs = !!contracts && contracts.rows.some(r => r.monthlyArs > 0);
  const tiempos = usingSimulatedTimes
    ? <span className="text-[10px] font-black uppercase bg-amber-100 text-amber-800 px-2 py-1 rounded">Con tiempos simulados</span>
    : null;
  const detailStat = agenda && agendaDetail !== undefined
    ? (agendaDetail === null ? agenda.total : agenda.rows.filter(r => r.label === agendaDetail)[0])
    : undefined;

  // --- Agenda ---
  const ag = agenda ? agenda.total : null;
  const ab = agendaBaseline ? agendaBaseline.total : undefined;
  const agendaMetrics: KpiMetric[] = ag ? [
    { label: 'Horas hábiles (clínica abierta)', value: `${formatCount(ag.potentialHours)} h`, delta: diffNum(ag.potentialHours, ab && ab.potentialHours, 'h'), sub: lines(was(ab && ab.potentialHours, fmtH)), title: 'Horas hábiles de la clínica en los meses con agenda cargada' },
    { label: 'Horas de agenda abierta', value: `${formatCount(ag.agendaHours)} h`, delta: diffNum(ag.agendaHours, ab && ab.agendaHours, 'h'), sub: lines(was(ab && ab.agendaHours, fmtH)), title: 'Horas con la agenda abierta (limitadas a las horas hábiles de cada mes)' },
    { label: 'Horas de adquisición', value: `${formatCount(ag.usedHours)} h`, delta: diffNum(ag.usedHours, ab && ab.usedHours, 'h'), sub: lines(was(ab && ab.usedHours, fmtH)) },
    { label: 'Cobertura de agenda', value: ag.coverage !== null ? `${ag.coverage.toFixed(1)}%` : NA, delta: diffPct(ag.coverage, ab && ab.coverage), sub: lines(was(ab && ab.coverage, fmtPct)), title: 'Horas de agenda abierta / horas hábiles de la clínica' },
    { label: 'Utilización efectiva de agenda', value: colored(ag.effective, ag.effective !== null ? `${ag.effective.toFixed(1)}%` : ''), delta: diffPct(ag.effective, ab && ab.effective), sub: lines(was(ab && ab.effective, fmtPct)), title: 'Horas de adquisición / horas de agenda abierta' },
  ] : [];

  // --- Productividad ---
  const targetStat = agenda ? { target: agenda.total.targetStudies, gap: agenda.total.studyGap } : { target: total.targetStudies, gap: total.studyGap };
  const baseTarget = agendaBaseline ? { target: agendaBaseline.total.targetStudies, gap: agendaBaseline.total.studyGap } : (base ? { target: base.targetStudies, gap: base.studyGap } : undefined);
  const prodMetrics: KpiMetric[] = [
    { label: utilLabel, value: colored(total.util, `${total.util.toFixed(1)}%`), delta: diffPct(total.util, base && base.util), sub: lines(`${total.gap > 0 ? '+' : ''}${total.gap.toFixed(1)} % vs objetivo ${TARGET_UTILIZATION} %`, was(base && base.util, fmtPct)), title: 'Horas usadas / horas hábiles de la flota' },
    { label: wording.studies, value: formatCount(total.studies), delta: diffNum(total.studies, base && base.studies), sub: lines(`${formatCount(total.avgStudiesPerMonth)} por mes`, was(base && base.studies, formatCount)) },
    { label: `Estudios objetivo (${TARGET_UTILIZATION} %${agenda ? ' de la agenda' : ''})`, value: targetStat.target !== null ? <span className="text-blue-700">{formatCount(targetStat.target)}</span> : NA, delta: diffNum(targetStat.target, baseTarget && baseTarget.target), sub: lines(was(baseTarget && baseTarget.target, formatCount)), title: 'Estudios que cabrían en el objetivo con la mezcla real de cada equipo; el total suma los objetivos por equipo' },
    { label: 'Diferencia vs objetivo (estudios)', value: targetStat.gap !== null ? <span className="text-gray-600">{`${Math.round(targetStat.gap) > 0 ? '+' : ''}${formatCount(targetStat.gap)}`}</span> : NA, delta: diffNum(targetStat.gap, baseTarget && baseTarget.gap), sub: lines('realizados − objetivo', was(baseTarget && baseTarget.gap, fmtSigned)) },
  ];

  // --- Costos ---
  const ct = contracts ? contracts.total : null;
  const cb = contractsBaseline ? contractsBaseline.total : undefined;
  const mark = ct && !ct.complete ? '*' : '';
  const costMetrics: KpiMetric[] = ct && ct.monthlyUsd !== null ? [
    { label: 'Contrato mensual', value: `${formatUsd(ct.monthlyUsd)}${mark}`, sub: lines(contracts && contracts.withoutContract.length > 0 ? `${contracts.withoutContract.length} sin contrato cargado` : (scenario ? 'contratos de los equipos que siguen' : 'contratos vigentes de la flota activa'), was(cb && cb.monthlyUsd, n => formatUsd(n))), delta: diffUsd(ct.monthlyUsd, cb && cb.monthlyUsd, 0, false) },
    { label: 'Acumulado del período', value: `${formatUsd(ct.accumulatedUsd || 0)}${mark}`, sub: lines(`${ct.months} ${ct.months === 1 ? 'mes' : 'meses'}`, was(cb && cb.accumulatedUsd, n => formatUsd(n))), delta: diffUsd(ct.accumulatedUsd, cb && cb.accumulatedUsd, 0, false) },
    { label: 'Mantenimiento por estudio', value: ct.perStudyUsd !== null ? `${formatUsd(ct.perStudyUsd, 2)}${mark}` : NA, sub: lines(`sobre ${formatCount(ct.studies)} estudios`, was(cb && cb.perStudyUsd, n => formatUsd(n, 2))), delta: diffUsd(ct.perStudyUsd, cb && cb.perStudyUsd, 2, false) },
  ] : [];

  // --- Dependencia ---
  const dp = dependency ? dependency.total : null;
  const db = dependencyBaseline ? dependencyBaseline.total : undefined;
  const depMetrics: KpiMetric[] = dp ? [
    { label: 'Equipos que generan dependencia', value: <span className={dp.equipmentsWithDependency > 0 ? 'text-rose-600' : undefined}>{dp.equipmentsWithDependency} <span className="text-sm text-gray-400">de {dp.activeEquipments}</span></span>, delta: diffNum(dp.equipmentsWithDependency, db && db.equipmentsWithDependency, '', false), sub: lines(db && `Actual: ${db.equipmentsWithDependency} de ${db.activeEquipments}`), title: `Equipos que hacen más del ${DEPENDENCY_THRESHOLD} % de los estudios de alguna categoría secundaria` },
    { label: 'Categorías secundarias con dependencia', value: <span className={dp.dependentCategories > 0 ? 'text-rose-600' : undefined}>{dp.dependentCategories} <span className="text-sm text-gray-400">de {dp.categories}</span></span>, delta: diffNum(dp.dependentCategories, db && db.dependentCategories, '', false), sub: lines(db && `Actual: ${db.dependentCategories} de ${db.categories}`) },
    { label: 'Estudios en esas categorías', value: dp.shareOfStudies !== null ? `${dp.shareOfStudies.toFixed(1)}%` : NA, delta: diffPct(dp.shareOfStudies, db && db.shareOfStudies, false), sub: lines(`${formatCount(dp.studiesInDependent)} de ${formatCount(dp.studies)} estudios`, was(db && db.shareOfStudies, fmtPct)) },
  ] : [];

  const commonTable = {
    period,
    utilHeader: utilLabel,
    studiesHeader: wording.studies,
    totalLabel,
    fleet,
    baseline: baselineFleet,
    agendaBaseline: agendaBaseline || undefined,
    removed,
    onToggleEq,
    onDetail,
  };
  const scenarioSuffix = scenario ? ' (escenario simulado)' : '';

  return (
    <>
      {picker && onToggleEq && (
        <EquipmentPicker equipments={picker.equipments} selected={picker.selected} removed={removed || []} onToggle={onToggleEq} onAll={picker.onAll} scenario={scenario} />
      )}
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
        <KpiBanner title="Métricas de agenda" icon={<Calendar className="text-blue-400" size={18}/>} metrics={agendaMetrics} open={open === 'agenda'} onToggle={() => toggle('agenda')} emptyMessage="Cargá la hoja CAPACIDAD DE AGENDA para ver estas métricas." />
        <KpiBanner title="Métricas de productividad" icon={<BarChart2 className="text-emerald-400" size={18}/>} metrics={prodMetrics} open={open === 'productividad'} onToggle={() => toggle('productividad')} />
        <KpiBanner title="Métricas de costos" icon={<Briefcase className="text-amber-400" size={18}/>} metrics={costMetrics} open={open === 'costos'} onToggle={() => toggle('costos')} emptyMessage="Cargá la hoja CONTRATOS VIGENTES (con contratos de los equipos activos) para ver estas métricas." />
        <KpiBanner title="Equipos que generan dependencia" icon={<AlertTriangle className="text-rose-400" size={18}/>} metrics={depMetrics} open={open === 'dependencia'} onToggle={() => toggle('dependencia')} />
      </div>

      {open === 'agenda' && agenda && (
        <FleetTable
          {...commonTable}
          title={`Agenda por equipo${scenarioSuffix}`}
          iconClass="text-blue-400"
          group="agenda"
          agenda={agenda}
          onAgendaDetail={setAgendaDetail}
          badges={tiempos}
          footnote={`Horas hábiles = horas en que la clínica estuvo abierta; horas de agenda = horas con la agenda abierta (limitadas a las horas hábiles de cada mes). Cobertura de agenda = horas de agenda / horas hábiles; utilización efectiva = horas de adquisición / horas de agenda (hacé clic para ver cómo se reparte entre Neuro, Cuerpo y Commodities). Solo cuentan los meses con agenda cargada: un mes sin dato queda fuera de todas.${scenario ? ' La agenda de cada equipo no cambia con la simulación; en el total sólo quedan los equipos que siguen.' : ' Destildar un equipo lo saca del total.'}`}
        />
      )}

      {open === 'productividad' && (
        <>
          <FleetTable
            {...commonTable}
            title={`Productividad por equipo${scenarioSuffix}`}
            iconClass="text-emerald-400"
            group="productividad"
            agenda={agenda || undefined}
            onAgendaDetail={agenda ? setAgendaDetail : undefined}
            badges={tiempos}
            footnote={`Misma tabla que ${scenario ? 'en el simulador' : 'en Productividad flota actual'}, sin las columnas de cobertura, horas de agenda y costos. Estudios objetivo = estudios que cabrían en el ${TARGET_UTILIZATION} % de ${agenda ? 'las horas de agenda abierta' : 'las horas hábiles'} con la mezcla real de cada equipo${scenario ? ' en el escenario (incluye lo reubicado)' : ''}; el total suma los objetivos por equipo. Hacé clic en la utilización o en el promedio de estudios para ver el detalle mes a mes.`}
          />
          {showChart && <ProductivityChartSection />}
        </>
      )}

      {open === 'costos' && contracts && (
        <FleetTable
          {...commonTable}
          title={`Costos de mantenimiento por equipo${scenarioSuffix}`}
          iconClass="text-amber-400"
          group="costos"
          contracts={contracts}
          badges={<>
            {hasArs && <FxRateControl rate={fx.rate} source={fx.source} date={fx.date} status={fxStatus} onChange={setFxManual} />}
            {tiempos}
          </>}
          footnote={`Contrato mensual = importe del contrato de mantenimiento vigente (la parte en pesos se convierte con el dólar oficial vendedor). Mantenimiento por estudio = contrato mensual × meses considerados / estudios hechos; usa el contrato vigente para todos los meses.${scenario ? ' Los equipos dados de baja dejan de pagar su contrato en el escenario.' : ''}${contracts.missingRate ? ' * Falta la cotización: solo incluye la parte en USD.' : ''}`}
        />
      )}

      {open === 'dependencia' && dependency && (
        <DependencyDetail summary={dependency} baseline={dependencyBaseline || undefined} scenario={scenario} period={period} />
      )}

      <AgendaCompositionModal
        stat={detailStat}
        name={agendaDetail === null || agendaDetail === undefined ? totalLabel : agendaDetail}
        year={year}
        onClose={() => setAgendaDetail(undefined)}
        scenarioLabel={scenario ? 'escenario simulado' : undefined}
      />
    </>
  );
};

/** Equipos que se consideran en las cifras de los banners (botones tildables); siempre queda al menos uno. */
const EquipmentPicker: React.FC<{
  equipments: string[];
  selected: Set<string>;
  removed: string[];
  onToggle: (eq: string) => void;
  onAll: () => void;
  scenario: boolean;
}> = ({ equipments, selected, removed, onToggle, onAll, scenario }) => {
  const allOn = equipments.every(e => removed.indexOf(e) >= 0 || selected.has(e));
  return (
    <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-4 px-5">
      <div className="flex items-center gap-3 mb-2">
        <span className="text-[10px] font-bold text-gray-500 uppercase tracking-wider">Equipos considerados en las cifras</span>
        <button onClick={onAll} disabled={allOn} className={`text-[10px] font-bold ${allOn ? 'text-gray-300 cursor-default' : 'text-blue-600 hover:underline'}`}>Todos</button>
      </div>
      <div className="flex gap-1.5 flex-wrap">
        {equipments.map(eq => {
          const out = removed.indexOf(eq) >= 0;
          const on = !out && selected.has(eq);
          const last = on && equipments.filter(e => removed.indexOf(e) < 0 && selected.has(e)).length <= 1;
          return (
            <button
              key={eq}
              onClick={() => onToggle(eq)}
              disabled={out || last}
              title={out ? 'Dado de baja en el escenario' : (last ? 'Tiene que quedar al menos un equipo' : (on ? 'Hacé clic para sacarlo de las cifras' : 'Hacé clic para incluirlo en las cifras'))}
              className={`px-2.5 py-1.5 text-[10px] font-bold rounded border transition-colors ${out ? 'bg-gray-100 text-gray-300 border-gray-100 line-through cursor-not-allowed' : (on ? 'bg-blue-100 text-blue-800 border-blue-300 shadow-sm' : 'bg-white text-gray-400 border-gray-200 hover:bg-gray-100')} ${last ? 'cursor-default' : ''}`}
            >
              {eq}
            </button>
          );
        })}
      </div>
      {scenario && <p className="text-[11px] text-gray-400 mt-2">Los equipos dados de baja no se pueden elegir. Si dejás afuera un equipo que recibe estudios del escenario, esos estudios no se cuentan; la flota actual de referencia se arma con los mismos equipos.</p>}
    </div>
  );
};

/** Detalle por equipo de la dependencia: categorías secundarias donde supera el umbral y qué parte de sus estudios son. */
const DependencyDetail: React.FC<{
  summary: calc.DependencySummary;
  baseline?: calc.DependencySummary;
  scenario: boolean;
  period: string;
}> = ({ summary, baseline, scenario, period }) => {
  const { canSeeView } = useAuth();
  // Orden por defecto: del equipo con más categorías con dependencia al que tiene menos (después, el que más
  // estudios tiene en ellas y por nombre); los equipos fuera del cálculo quedan al final
  const sortedRows = summary.rows.slice().sort((a, b) =>
    (a.isActive === b.isActive ? 0 : a.isActive ? -1 : 1)
    || b.categories.length - a.categories.length
    || b.studiesInDependent - a.studiesInDependent
    || (a.eq < b.eq ? -1 : a.eq > b.eq ? 1 : 0));
  return (
  <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
    <div className="bg-gray-800 p-5 px-6">
      <h3 className="text-lg font-bold text-white flex items-center gap-2"><AlertTriangle className="text-rose-400" size={20}/> Dependencia por equipo{scenario ? ' (escenario simulado)' : ''}</h3>
      {period && <p className="text-xs text-gray-400 mt-1">Acumulado: {period}</p>}
    </div>
    <div className="overflow-x-auto">
      <table className="w-full text-sm text-left">
        <thead className="text-[10px] text-gray-500 uppercase bg-gray-50 border-b border-gray-200">
          <tr>
            <th className="px-6 py-4 font-bold w-[250px]">Equipo de Resonancia</th>
            {baseline && <th className="px-6 py-4 text-center font-bold">Categorías con dependencia (actual)</th>}
            <th className="px-6 py-4 text-center font-bold">Categorías con dependencia</th>
            <th className="px-6 py-4 text-center font-bold">Estudios en esas categorías</th>
            <th className="px-6 py-4 text-center font-bold">% de sus estudios</th>
            <th className="px-6 py-4 font-bold border-l border-gray-100 min-w-[320px]">Categorías secundarias (% que hace el equipo)</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-100">
          {sortedRows.map(row => {
            const before = baseline ? baseline.rows.filter(r => r.eq === row.eq)[0] : undefined;
            return (
              <tr key={row.eq} className={`transition-colors ${row.isActive ? 'hover:bg-gray-50' : 'bg-gray-50 opacity-40 grayscale'}`}>
                <td className="px-6 py-4">
                  <span className={`font-bold text-xs ${row.isActive ? 'text-gray-800' : 'text-gray-400 line-through'}`}>{row.eq}</span>
                </td>
                {baseline && (
                  <td className="px-6 py-4 text-center">
                    <span className="text-sm font-bold text-gray-500">{before ? before.categories.length : '—'}</span>
                  </td>
                )}
                <td className="px-6 py-4 text-center">
                  <span className={`text-sm font-bold ${row.categories.length > 0 ? 'text-rose-600' : 'text-gray-400'}`}>{row.isActive ? row.categories.length : '—'}</span>
                </td>
                <td className="px-6 py-4 text-center"><span className="text-sm font-bold text-gray-600">{row.isActive ? formatCount(row.studiesInDependent) : '—'}</span></td>
                <td className="px-6 py-4 text-center"><span className="text-sm font-bold text-gray-600">{row.shareOfStudies !== null ? `${row.shareOfStudies.toFixed(1)}%` : '—'}</span></td>
                <td className="px-6 py-3 border-l border-gray-100">
                  {row.categories.length === 0 ? <span className="text-gray-300 font-bold">—</span> : (
                    <div className="flex flex-wrap gap-1.5">
                      {row.categories.map(c => (
                        <span key={c.category} title={`${formatCount(c.topCount)} de ${formatCount(c.total)} estudios de la categoría`} className="text-[11px] font-bold bg-rose-50 text-rose-700 border border-rose-200 rounded px-2 py-0.5">{c.category} · {c.topShare.toFixed(1)}%</span>
                      ))}
                    </div>
                  )}
                </td>
              </tr>
            );
          })}
          <tr className="bg-gray-100 border-t-2 border-gray-300">
            <td className="px-6 py-4 font-black text-gray-800 text-xs uppercase tracking-widest pl-12">{scenario ? 'Total Flota Simulada' : 'Total Flota Activa'}</td>
            {baseline && <td className="px-6 py-4 text-center"><span className="text-base font-black text-gray-500">{baseline.total.dependentCategories}</span></td>}
            <td className="px-6 py-4 text-center"><span className="text-base font-black text-gray-700">{summary.total.dependentCategories}</span></td>
            <td className="px-6 py-4 text-center"><span className="text-base font-black text-gray-700">{formatCount(summary.total.studiesInDependent)}</span></td>
            <td className="px-6 py-4 text-center"><span className="text-base font-black text-gray-700">{summary.total.shareOfStudies !== null ? `${summary.total.shareOfStudies.toFixed(1)}%` : '—'}</span></td>
            <td className="px-6 py-4 border-l border-gray-200 text-xs font-bold text-gray-500">{summary.total.categories} categorías secundarias con estudios</td>
          </tr>
        </tbody>
      </table>
    </div>
    <p className="px-6 py-3 text-[11px] text-gray-400 border-t border-gray-100">
      Un equipo genera dependencia cuando hizo más del {DEPENDENCY_THRESHOLD} % de los estudios (cantidad) de una categoría secundaria entre los equipos activos, en los meses elegidos.
      En la fila del total, los estudios son los de toda la flota en esas categorías.
      {scenario
        ? ' En el escenario, los estudios de los equipos dados de baja se suman a los equipos que los reciben, y los porcentajes se calculan entre los equipos que siguen; "actual" es la flota completa sin simular. No usa el selector de equipos: solo cambia por los equipos dados de baja.'
        : ' Esta tabla y su banner no usan el selector de equipos: miden siempre la flota completa.'}
      {canSeeView('dependencia') && ' Para ver todas las categorías, filtrá la matriz de ¿Cuánto depende la red de cada equipo?.'}
    </p>
  </div>
  );
};
