import React from "react";
import { Target, CheckSquare, Square, Briefcase } from "lucide-react";
import { useModel } from "../model/ModelContext";

export const SimConfigPanel: React.FC = () => {
  const { data, simulationYear, setSimulationYear, disabledEqs, toggleDisabledEq, orphanedStudies } = useModel();

  return (
    <>
      <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-6 mb-6">
        <div className="flex flex-col lg:flex-row gap-8">
           <div className="lg:w-1/3">
              <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2 mb-4">
                 <Target className="text-orange-500"/> Configuración de Escenario
              </h3>
              <div className="space-y-4">
                 <div>
                   <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2">Año Base para Simulación</label>
                   <select value={simulationYear} onChange={e => setSimulationYear(parseInt(e.target.value))} className="w-full bg-gray-50 border border-gray-300 text-sm rounded-lg p-2.5 font-bold outline-none focus:ring-2 focus:ring-orange-500">
                     {data.years.map(yr => <option key={yr} value={yr}>{yr}</option>)}
                   </select>
                 </div>
                 <div>
                   <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2">Equipos a redistribuir / dar de baja</label>
                   <div className="flex flex-col gap-2 max-h-[150px] overflow-y-auto custom-scrollbar pr-2">
                      {data.equipments.map(eq => (
                        <label key={eq} className={`flex items-center gap-2 text-sm font-bold px-3 py-2 rounded-lg border cursor-pointer select-none transition-all ${disabledEqs.includes(eq) ? 'bg-red-50 border-red-200 text-red-700 shadow-sm' : 'bg-white border-gray-200 text-gray-500 hover:bg-gray-50'}`}>
                          <input type="checkbox" checked={disabledEqs.includes(eq)} onChange={() => toggleDisabledEq(eq)} className="hidden" />
                          {disabledEqs.includes(eq) ? <CheckSquare size={16}/> : <Square size={16}/>}
                          <span className="truncate">{eq}</span>
                        </label>
                      ))}
                   </div>
                 </div>
              </div>
           </div>

           <div className="lg:w-2/3 lg:border-l border-gray-100 lg:pl-8 flex flex-col justify-center">
              {disabledEqs.length === 0 ? (
                 <div className="text-center p-8 bg-gray-50 rounded-2xl border border-gray-200 border-dashed">
                    <Briefcase size={40} className="mx-auto text-gray-300 mb-3"/>
                    <p className="text-gray-500 font-medium">Selecciona al menos un equipo en el panel izquierdo para redistribuir su carga de trabajo en la red.</p>
                 </div>
              ) : (
                 <div className="grid grid-cols-2 gap-4">
                    <div className="bg-orange-50 border border-orange-100 p-5 rounded-2xl">
                       <p className="text-[10px] font-bold text-orange-800 uppercase tracking-wider mb-1">Carga a Distribuir</p>
                       <p className="text-4xl font-black text-orange-600">
                          {Object.values(orphanedStudies).reduce((a, b) => a + b, 0).toLocaleString()}
                       </p>
                       <p className="text-xs text-orange-700/70 font-medium mt-1">Estudios reubicados (Año base: {simulationYear})</p>
                    </div>
                    <div className="bg-emerald-50 border border-emerald-100 p-5 rounded-2xl">
                       <p className="text-[10px] font-bold text-emerald-800 uppercase tracking-wider mb-1">Flota Operativa</p>
                       <p className="text-4xl font-black text-emerald-600">
                          {data.equipments.length - disabledEqs.length}
                       </p>
                       <p className="text-xs text-emerald-700/70 font-medium mt-1">Equipos absorbiendo carga</p>
                    </div>
                 </div>
              )}
           </div>
        </div>
      </div>
    </>
  );
};
