import React, { useState } from "react";
import { MONTH_NAMES, TARGET_UTILIZATION } from "../config";
import * as calc from "../calc";
import { AgendaCompositionModal } from "../components/AgendaCompositionModal";
import { FleetTable } from "../components/FleetTable";
import { FxRateControl } from "../components/FxRateControl";
import { useModel } from "../model/ModelContext";
import { SimMonthlyDetailModal } from "./SimMonthlyDetailModal";

/**
 * Simulador: la tabla de utilización de la vista 1, pero con el escenario simulado
 * (equipos que siguen operando + estudios reubicados), junto a la utilización original de cada equipo.
 */
export const SimFleetTable: React.FC = () => {
  const { simFleet, simulationYear, simExcludedMonths, disabledEqs, data, usingSimulatedTimes, setSimFleetDetail, simAgenda, simContracts, fx, fxStatus, setFxManual } = useModel();
  // Ventana de distribución por categoría de la agenda: undefined = cerrada, null = total de la flota simulada
  const [agendaDetail, setAgendaDetail] = useState<string | null | undefined>(undefined);
  if (!simFleet) return null;

  const months = MONTH_NAMES.filter(m => !simExcludedMonths.has(m));
  const period = months.length === 0 ? '' : `${calc.describeMonths(months)} ${simulationYear} · ${months.length} ${months.length === 1 ? 'mes' : 'meses'}`;
  const wording = calc.periodWording(months.length, simulationYear);
  const shown = { ...simFleet.sim, rows: simFleet.sim.rows.filter(r => r.isActive) };
  const removed = data.equipments.filter(e => disabledEqs.includes(e));
  const hasArs = !!simContracts && simContracts.rows.some(r => r.monthlyArs > 0);
  const compositionStat = simAgenda && agendaDetail !== undefined
    ? (agendaDetail === null ? simAgenda.sim.total : simAgenda.sim.rows.filter(r => r.label === agendaDetail)[0])
    : undefined;

  return (
    <div className="mb-8">
      <FleetTable
        title={`Flota Simulada: ${wording.simUtil} vs Objetivo`}
        iconClass="text-orange-400"
        period={period}
        utilHeader={wording.simUtil}
        studiesHeader={wording.studies}
        totalLabel="Total Flota Simulada"
        fleet={shown}
        baseline={simFleet.original}
        agenda={simAgenda ? simAgenda.sim : undefined}
        agendaBaseline={simAgenda ? simAgenda.original : undefined}
        contracts={simContracts || undefined}
        onAgendaDetail={simAgenda ? setAgendaDetail : undefined}
        removed={removed}
        onDetail={setSimFleetDetail}
        badges={<>
          {hasArs && <FxRateControl rate={fx.rate} source={fx.source} date={fx.date} status={fxStatus} onChange={setFxManual} />}
          {usingSimulatedTimes && (
            <span className="text-[10px] font-black uppercase bg-amber-100 text-amber-800 px-2 py-1 rounded">Con tiempos simulados</span>
          )}
        </>}
        footnote={<>
          Cada equipo incluye su propia producción más los estudios que se le reubican. "Utilización Original" es la situación actual del equipo; en el total, la de toda la flota antes de dar de baja equipos.
          Los estudios de los equipos fuera de servicio que no se asignan a ningún equipo no se cuentan en la flota simulada.
          Hacé clic en la utilización o en el promedio de estudios para ver el detalle mes a mes.
          {simAgenda
            ? ` La agenda abierta de cada equipo no cambia con la simulación: la cobertura se mantiene y la utilización efectiva muestra cuánto de esa agenda ocuparía la nueva carga (más de 100 % significa que la agenda abierta hoy no alcanzaría; hacé clic para ver el reparto por categoría). El total compara la flota simulada con la flota actual completa. Estudios objetivo = estudios que cabrían en el ${TARGET_UTILIZATION} % de las horas de agenda abierta al tiempo promedio por estudio de la mezcla de cada equipo en el escenario (incluye lo reubicado); el total suma los objetivos de los equipos que siguen.`
            : ` Estudios objetivo = estudios que cabrían en el ${TARGET_UTILIZATION} % de las horas hábiles al tiempo promedio por estudio de la mezcla de cada equipo en el escenario (incluye lo reubicado); el total suma los objetivos de los equipos que siguen.`}
          {simContracts && ` Los equipos dados de baja dejan de pagar su contrato en el escenario: el mantenimiento por estudio es el de los contratos de los equipos que siguen sobre los estudios del escenario.${simContracts.missingRate ? ' * Falta la cotización: solo incluye la parte en USD.' : ''}`}
        </>}
      />
      <SimMonthlyDetailModal />
      <AgendaCompositionModal
        stat={compositionStat}
        name={agendaDetail === null || agendaDetail === undefined ? 'Total Flota Simulada' : agendaDetail}
        year={simulationYear}
        onClose={() => setAgendaDetail(undefined)}
        scenarioLabel="escenario simulado"
      />
    </div>
  );
};
