import React, { useState } from "react";

export type FxSource = 'manual' | 'live' | 'fallback' | 'none';

interface FxRateControlProps {
  /** Cotización en uso (pesos por USD) y de dónde sale. */
  rate: number | null;
  source: FxSource;
  /** Fecha de la cotización en vivo (ISO), si se conoce. */
  date: string;
  /** Estado de la consulta en vivo. */
  status: 'loading' | 'ok' | 'error';
  /** Fija una cotización a mano; null vuelve a la automática. */
  onChange: (rate: number | null) => void;
}

const SOURCE_LABEL = (source: FxSource, date: string, status: 'loading' | 'ok' | 'error'): string => {
  if (source === 'manual') return 'Valor manual';
  if (source === 'live') {
    const d = date ? new Date(date) : null;
    return d && !isNaN(d.getTime()) ? `En vivo · ${d.toLocaleDateString('es-AR')}` : 'En vivo';
  }
  if (source === 'fallback') return 'Valor de respaldo';
  return status === 'loading' ? 'Consultando…' : 'Sin cotización: ingresá un valor';
};

/**
 * Cotización del dólar oficial vendedor con la que se convierte a USD la parte en pesos de los contratos.
 * Muestra de dónde sale el valor y permite reemplazarlo a mano.
 */
export const FxRateControl: React.FC<FxRateControlProps> = ({ rate, source, date, status, onChange }) => {
  const [draft, setDraft] = useState<string | null>(null);
  const shown = draft !== null ? draft : (rate === null ? '' : String(Math.round(rate * 100) / 100));

  const commit = (text: string) => {
    const n = parseFloat(text.replace(',', '.'));
    if (isFinite(n) && n > 0) onChange(n);
    setDraft(null);
  };

  return (
    <div className="flex items-center gap-2 bg-gray-700 rounded-lg px-3 py-1.5 text-[10px] font-bold text-gray-300 uppercase shrink-0">
      <span title="Cotización con la que se convierte a USD la parte en pesos de los contratos">USD oficial vendedor ($)</span>
      <input
        type="text"
        inputMode="decimal"
        value={shown}
        placeholder="—"
        onChange={(e) => setDraft(e.target.value)}
        onBlur={(e) => { if (draft !== null) commit(e.target.value); }}
        onKeyDown={(e) => { if (e.key === 'Enter') commit((e.target as HTMLInputElement).value); }}
        className="w-24 bg-gray-800 border border-gray-600 rounded px-2 py-1 text-xs text-white text-right focus:outline-none focus:border-blue-400"
      />
      <span className={source === 'none' ? 'text-amber-300' : 'text-gray-400'}>{SOURCE_LABEL(source, date, status)}</span>
      {source === 'manual' && (
        <button onClick={() => onChange(null)} className="text-blue-300 hover:text-blue-200 underline normal-case">usar automático</button>
      )}
    </div>
  );
};
