import React, { useEffect, useRef } from "react";
import { Activity, AlertCircle, Settings, Zap, Briefcase } from "lucide-react";
import { AuthProvider, useAuth } from "./auth/AuthContext";
import { DataQualityPanel } from "./components/DataQualityPanel";
import { FileUploader } from "./components/FileUploader";
import { OWN_HOURS_SHEETS } from "./config";
import { ModelProvider, useModel, ViewId } from "./model/ModelContext";
import { SummaryView } from "./views/SummaryView";
import { SimSummaryView } from "./views/SimSummaryView";
import { FleetView } from "./views/FleetView";
import { EvolutionView } from "./views/EvolutionView";
import { DependencyView } from "./views/DependencyView";
import { ExploreView } from "./views/ExploreView";
import { LoginScreen } from "./views/LoginScreen";
import { SimulatorTab } from "./sections/SimulatorTab";
import { Modals } from "./sections/Modals";

// El resumen, las cuatro preguntas de decisión y el detalle para explorar. Cada rol (src/auth/permissions.ts) ve solo algunas.
const VIEW_TABS: Array<{ id: ViewId; label: string; activeClass: string; align?: 'right' }> = [
  { id: 'resumen', label: 'Resumen', activeClass: 'border-blue-600 text-blue-600' },
  { id: 'flota', label: 'Productividad flota actual', activeClass: 'border-blue-600 text-blue-600' },
  { id: 'evolucion', label: '¿Cómo viene evolucionando?', activeClass: 'border-blue-600 text-blue-600' },
  { id: 'dependencia', label: '¿Cuánto depende la red de cada equipo?', activeClass: 'border-blue-600 text-blue-600' },
  { id: 'simulacion', label: 'Simulación de baja de RM', activeClass: 'border-orange-500 text-orange-600' },
  { id: 'simresumen', label: 'Resumen de la simulación', activeClass: 'border-orange-500 text-orange-600' },
  { id: 'explorar', label: 'Explorar en detalle', activeClass: 'border-gray-700 text-gray-800', align: 'right' },
];

const AppShell: React.FC = () => {
  const { user, logout, canSeeView, capabilities } = useAuth();
  const { activeTab, setActiveTab, filesLoaded, qualityReport, isFetchingSheet, sheetError, processHoras, processHorasPropias, processTiempos, processAcumulado, processAgenda, processContratos, handleDevelopmentFetch, handleFileUpload, allFilesLoaded } = useModel();

  // Al ingresar se cargan los datos solos (lo mismo que el botón de Carga Rápida)
  const autoLoadStarted = useRef(false);
  useEffect(() => {
    if (autoLoadStarted.current) return;
    autoLoadStarted.current = true;
    handleDevelopmentFetch();
  }, []);

  const tabs = VIEW_TABS.filter(tab => canSeeView(tab.id));
  const currentTab = tabs.some(tab => tab.id === activeTab) ? activeTab : (tabs.length > 0 ? tabs[0].id : activeTab);

  return (
    <div className="min-h-screen bg-gray-50 p-6 text-gray-800 font-sans relative">
      <div className="max-w-[1400px] mx-auto">
        
        {/* HEADER DE CARGA Y TABS */}
        <div className="bg-white rounded-t-2xl shadow-sm border border-gray-200 p-6 print:hidden">
          <div className="flex flex-col md:flex-row justify-between gap-6 mb-6">
            <div>
              <h1 className="text-2xl font-bold flex items-center gap-2 text-gray-900">
                <Activity className="text-blue-600" /> Simulador de Productividad
              </h1>
            </div>
            <div className="flex flex-col items-end">
              <p className="text-xs text-gray-500 mb-2">
                <span className="font-bold text-gray-700">{user ? user.display : ''}</span>
                <button onClick={logout} className="ml-3 font-bold text-blue-600 hover:underline">Cerrar sesión</button>
              </p>
              {capabilities.cargaManual && (
                <button 
                  onClick={handleDevelopmentFetch} 
                  disabled={isFetchingSheet} 
                  className="bg-emerald-600 text-white px-5 py-2.5 rounded-xl font-bold text-sm hover:bg-emerald-700 disabled:opacity-50 flex items-center gap-2 shadow-sm transition-colors"
                >
                  {isFetchingSheet ? <Settings className="animate-spin" size={18}/> : <Zap size={18}/>}
                  Carga Rápida (Entorno Dev)
                </button>
              )}
              {sheetError && <p className="text-xs text-red-600 font-bold mt-2 flex items-center gap-1"><AlertCircle size={12}/> {sheetError}</p>}
            </div>
          </div>
          {capabilities.cargaManual && <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-7 gap-3 pt-4 border-t border-gray-100">
            <FileUploader name="HORAS HÁBILES (DMO / ELAS)" loaded={filesLoaded.HORAS_HABILES_MES} handler={handleFileUpload(processHoras)} />
            {OWN_HOURS_SHEETS.map(sheet => (
              <FileUploader key={sheet.key} name={`HORAS HÁBILES (${sheet.label.toUpperCase()})`} loaded={filesLoaded[sheet.key]} handler={handleFileUpload(processHorasPropias(sheet))} />
            ))}
            <FileUploader name="TIEMPOS MRI" loaded={filesLoaded.TIEMPOS_MRI_CURADO} handler={handleFileUpload(processTiempos)} />
            <FileUploader name="DATA ACUMULADA" loaded={filesLoaded.ACUMULADO_CATEGORIZADO} handler={handleFileUpload(processAcumulado)} />
            <FileUploader name="CAPACIDAD DE AGENDA" loaded={filesLoaded.AGENDA} handler={handleFileUpload(processAgenda)} />
            <FileUploader name="CONTRATOS VIGENTES" loaded={filesLoaded.CONTRATOS} handler={handleFileUpload(processContratos)} />
          </div>}
        </div>
        <div className="flex border-b border-gray-200 mb-6 bg-white rounded-b-2xl px-2 shadow-sm print:hidden overflow-x-auto">
            {tabs.map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`py-3 px-5 font-bold text-sm border-b-2 transition-colors whitespace-nowrap flex items-center gap-2 ${tab.align === 'right' ? 'ml-auto ' : ''}${currentTab === tab.id ? tab.activeClass : 'border-transparent text-gray-500 hover:text-gray-800'}`}
              >
                {tab.id === 'simulacion' && <Briefcase size={16} />} {tab.label}
              </button>
            ))}
        </div>

        {qualityReport && capabilities.calidadDeDatos && <DataQualityPanel report={qualityReport} />}

        {!allFilesLoaded ? (
          <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-12 text-center text-gray-500 print:hidden">
            <Settings size={48} className="text-gray-300 mb-4 mx-auto animate-spin-slow" />
            <h3 className="text-xl font-medium">
              {isFetchingSheet
                ? 'Cargando los datos…'
                : (capabilities.cargaManual ? 'Carga los archivos o utiliza el botón de Carga Rápida para comenzar' : (sheetError ? 'No se pudieron cargar los datos' : 'Cargando los datos…'))}
            </h3>
            {!isFetchingSheet && !capabilities.cargaManual && sheetError && (
              <button onClick={handleDevelopmentFetch} className="mt-5 bg-blue-600 text-white px-5 py-2.5 rounded-xl font-bold text-sm hover:bg-blue-700 transition-colors">Reintentar</button>
            )}
          </div>
        ) : (
          <div className="animate-in fade-in duration-500">
            {currentTab === 'resumen' && <SummaryView />}
            {currentTab === 'flota' && <FleetView />}
            {currentTab === 'evolucion' && <EvolutionView />}
            {currentTab === 'dependencia' && <DependencyView />}
            {currentTab === 'simulacion' && <SimulatorTab />}
            {currentTab === 'simresumen' && <SimSummaryView />}
            {currentTab === 'explorar' && <ExploreView />}

          </div>
        )}
      </div>

      <Modals />
    </div>
  );
};

// Sin sesión iniciada solo se ve la pantalla de ingreso; al ingresar se arma el modelo (y se cargan los datos).
// La clave del modelo es el usuario: al cerrar sesión o cambiar de usuario se descarta todo lo cargado.
const Gate: React.FC = () => {
  const { user } = useAuth();
  if (!user) return <LoginScreen />;
  return (
    <ModelProvider key={user.username}>
      <AppShell />
    </ModelProvider>
  );
};

const ProductividadResonadoresApp: React.FC = () => (
  <AuthProvider>
    <Gate />
  </AuthProvider>
);

export default ProductividadResonadoresApp;
