export const sheetCsvUrl = (gid: number): string =>
  `https://docs.google.com/spreadsheets/d/${SHEET_ID}/export?format=csv&gid=${gid}`;

// --- CONTRATOS EN PESOS: CONVERSIÓN A USD ---
// Los contratos con una parte en pesos (p. ej. Siemens) se llevan a USD con el dólar oficial vendedor.
// La app consulta la cotización actual al abrirse; si no puede, usa este valor de respaldo (pesos por
// dólar), y si tampoco hay, deja la parte en pesos sin convertir y lo avisa. El valor también se puede
// cambiar a mano desde la tabla.
export const FX_LIVE_URL = "https://dolarapi.com/v1/dolares/oficial";
export const FX_FALLBACK_ARS_PER_USD: number | null = null;

